window.CODE_INDEX = {"classes":{"BackPressedHandler":{"code":"interface BackPressedHandler {\n    fun onBackPressed(): Boolean\n}","file":"app/src/main/java/org/wikipedia/BackPressedHandler.kt","kind":"interface","line":3,"members":{"onBackPressed":[4,4]},"supers":[]},"CommunicationBridge":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"]],"code":"@SuppressLint(\"AddJavascriptInterface\", \"SetJavaScriptEnabled\")\nclass CommunicationBridge constructor(private val communicationBridgeListener: CommunicationBridgeListener) {\n    private val eventListeners = HashMap<String, MutableList<JSEventListener>>()\n    private var isMetadataReady = false\n    private var isPcsReady = false\n    private val pendingJSMessages = ArrayList<String>()\n    private val pendingEvals = HashMap<String, ValueCallback<String>>()\n\n    fun interface JSEventListener {\n        fun onMessage(messageType: String, messagePayload: JsonObject?)\n    }\n\n    interface CommunicationBridgeListener {\n        val webView: WebView\n        val model: PageViewModel\n        val isPreview: Boolean\n        val toolbarMargin: Int\n        val messageCardHeight: Float\n    }\n\n    init {\n        communicationBridgeListener.webView.settings.javaScriptEnabled = true\n        communicationBridgeListener.webView.settings.allowUniversalAccessFromFileURLs = true\n        communicationBridgeListener.webView.settings.mediaPlaybackRequiresUserGesture = false\n        communicationBridgeListener.webView.webChromeClient = CommunicatingChrome()\n        communicationBridgeListener.webView.addJavascriptInterface(PcsClientJavascriptInterface(), \"pcsClient\")\n    }\n\n    fun onPcsReady() {\n        isPcsReady = true\n        flushMessages()\n    }\n\n    fun loadBlankPage() {\n        communicationBridgeListener.webView.loadUrl(\"about:blank\")\n    }\n\n    fun onMetadataReady() {\n        isMetadataReady = true\n        flushMessages()\n    }\n\n    val isLoading: Boolean\n        get() = !(isMetadataReady && isPcsReady)\n\n    fun resetHtml(pageTitle: PageTitle) {\n        isPcsReady = false\n        isMetadataReady = false\n        pendingJSMessages.clear()\n        pendingEvals.clear()\n        if (communicationBridgeListener.model.shouldLoadAsMobileWeb) {\n            communicationBridgeListener.webView.loadUrl(pageTitle.uri)\n        } else {\n            communicationBridgeListener.webView.loadUrl(ServiceFactory.getRestBasePath(pageTitle.wikiSite) +\n                    RestService.PAGE_HTML_ENDPOINT + UriUtil.encodeURL(pageTitle.prefixedText))\n        }\n    }\n\n    fun cleanup() {\n        pendingJSMessages.clear()\n        pendingEvals.clear()\n        eventListeners.clear()\n        incomingMessageHandler?.removeCallbacksAndMessages(null)\n        incomingMessageHandler = null\n        communicationBridgeListener.webView.webViewClient = WebViewClient()\n        communicationBridgeListener.webView.removeJavascriptInterface(\"pcsClient\")\n        // Explicitly load a blank page into the WebView, to stop playback of any media.\n        loadBlankPage()\n    }\n\n    fun addListener(type: String, listener: JSEventListener) {\n        eventListeners.getOrPut(type) { ArrayList() }.add(listener)\n    }\n\n    fun execute(js: String) {\n        pendingJSMessages.add(js)\n        flushMessages()\n    }\n\n    fun evaluate(js: String, callback: ValueCallback<String>) {\n        pendingEvals[js] = callback\n        flushMessages()\n    }\n\n    fun evaluateImmediate(js: String, callback: ValueCallback<String?>?) {\n        communicationBridgeListener.webView.evaluateJavascript(js, callback)\n    }\n\n    private fun flushMessages() {\n        if (!isPcsReady || !isMetadataReady) {\n            return\n        }\n        for (jsString in pendingJSMessages) {\n            communicationBridgeListener.webView.evaluateJavascript(jsString, null)\n        }\n        pendingJSMessages.clear()\n        for ((key, callback) in pendingEvals) {\n            communicationBridgeListener.webView.evaluateJavascript(key, callback)\n        }\n        pendingEvals.clear()\n    }\n\n    private var incomingMessageHandler: Handler? = Handler(Looper.getMainLooper(), Handler.Callback { msg ->\n        val message = msg.obj as BridgeMessage\n        if (!eventListeners.containsKey(message.action)) {\n            L.e(\"No such message type registered: \" + message.action)\n            return@Callback false\n        }\n        try {\n            val listeners: List<JSEventListener> = eventListeners[message.action]!!\n            for (listener in listeners) {\n                listener.onMessage(message.action, message.data)\n            }\n        } catch (e: Exception) {\n            e.printStackTrace()\n            L.logRemoteError(e)\n        }\n        false\n    })\n\n    private class CommunicatingChrome : WebChromeClient() {\n        override fun onConsoleMessage(consoleMessage: ConsoleMessage): Boolean {\n            L.d(consoleMessage.sourceId() + \":\" + consoleMessage.lineNumber() + \" - \" + consoleMessage.message())\n            return true\n        }\n    }\n\n    private inner class PcsClientJavascriptInterface {\n        /**\n         * Called from Javascript to send a message packet to the Java layer. The message must be\n         * formatted in JSON, and URL-encoded.\n         *\n         * @param message JSON structured message received from the WebView.\n         */\n        @JavascriptInterface\n        @Synchronized\n        fun onReceiveMessage(message: String?) {\n            if (incomingMessageHandler != null) {\n                val bridgeMessage: BridgeMessage? = JsonUtil.decodeFromString(message.orEmpty())\n                if (bridgeMessage != null) {\n                    val msg = Message.obtain(incomingMessageHandler, MESSAGE_HANDLE_MESSAGE_FROM_JS, bridgeMessage)\n                    incomingMessageHandler!!.sendMessage(msg)\n                } else {\n                    L.w(\"Received malformed message: $message\")\n                }\n            }\n        }\n\n        @get:Synchronized\n        @get:JavascriptInterface\n        val setupSettings: String\n            get() = setUp(communicationBridgeListener.webView.context,\n                    communicationBridgeListener.model.title!!, communicationBridgeListener.isPreview,\n                    communicationBridgeListener.toolbarMargin, communicationBridgeListener.messageCardHeight)\n    }\n\n    @Serializable\n    private class BridgeMessage {\n        val action: String = \"\"\n        val data: JsonObject? = null\n    }\n\n    companion object {\n        private const val MESSAGE_HANDLE_MESSAGE_FROM_JS = 1\n    }\n}","file":"app/src/main/java/org/wikipedia/bridge/CommunicationBridge.kt","kind":"class","line":31,"members":{"BridgeMessage":[187,191],"CommunicatingChrome":[151,156],"CommunicationBridgeListener":[43,49],"JSEventListener":[39,41],"MESSAGE_HANDLE_MESSAGE_FROM_JS":[194,194],"PcsClientJavascriptInterface":[158,185],"addListener":[101,103],"cleanup":[89,99],"communicationBridgeListener":[32,32],"evaluate":[110,113],"evaluateImmediate":[115,117],"eventListeners":[33,33],"execute":[105,108],"flushMessages":[119,131],"incomingMessageHandler":[133,149],"isLoading":[73,73],"isMetadataReady":[34,34],"isPcsReady":[35,35],"loadBlankPage":[64,66],"onMetadataReady":[68,71],"onPcsReady":[59,62],"pendingEvals":[37,37],"pendingJSMessages":[36,36],"resetHtml":[76,87]},"supers":[]},"EnumCode":{"code":"interface EnumCode {\n    fun code(): Int\n}","file":"app/src/main/java/org/wikipedia/model/EnumCode.kt","kind":"interface","line":3,"members":{"code":[4,4]},"supers":[]},"HistoryEntry":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"]],"code":"@Serializable\n@Parcelize\n@TypeParceler<Date, DateParceler>()\n@Entity(\n    indices = [Index(value = [\"lang\", \"namespace\", \"apiTitle\"])]\n)\nclass HistoryEntry(\n    // TODO: change these properties back to val when HistoryEntry is no longer serializable. (i.e. when we update Tabs to be in the database instead of Prefs)\n    var authority: String = \"\",\n    var lang: String = \"\",\n    var apiTitle: String = \"\",\n    var displayTitle: String = \"\",\n    @PrimaryKey(autoGenerate = true) var id: Long = 0,\n    var namespace: String = \"\",\n    @Serializable(with = DateSerializer::class) var timestamp: Date = Date(),\n    var source: Int = SOURCE_INTERNAL_LINK,\n    var prevId: Long = -1,\n) : Parcelable {\n    constructor(title: PageTitle, source: Int, timestamp: Date = Date()) : this(title.wikiSite.authority(),\n        title.wikiSite.languageCode, title.text, title.displayText, namespace = title.namespace,\n        timestamp = timestamp, source = source) {\n        pageTitle = title\n    }\n\n    @IgnoredOnParcel\n    @Transient\n    @Ignore\n    private var pageTitle: PageTitle? = null\n\n    val title: PageTitle get() {\n        if (pageTitle == null) {\n            pageTitle = PageTitle(namespace, apiTitle, WikiSite(authority, lang)).also {\n                it.displayText = displayTitle\n            }\n        }\n        return pageTitle!!\n    }\n\n    // To be set when navigating back and forth between articles.\n    @IgnoredOnParcel\n    @Transient\n    @Ignore\n    var referrer: String? = null\n\n    companion object {\n        const val SOURCE_SEARCH = 1\n        const val SOURCE_INTERNAL_LINK = 2\n        const val SOURCE_EXTERNAL_LINK = 3\n        const val SOURCE_HISTORY = 4\n        const val SOURCE_LANGUAGE_LINK = 6\n        const val SOURCE_RANDOM = 7\n        const val SOURCE_MAIN_PAGE = 8\n        const val SOURCE_PLACES = 9\n        const val SOURCE_DISAMBIG = 10\n        const val SOURCE_READING_LIST = 11\n        const val SOURCE_FEED_BECAUSE_YOU_READ = 13\n        const val SOURCE_FEED_MOST_READ = 14\n        const val SOURCE_FEED_FEATURED = 15\n        const val SOURCE_NEWS = 16\n        const val SOURCE_FEED_MAIN_PAGE = 17\n        const val SOURCE_FEED_RANDOM = 18\n        const val SOURCE_GALLERY = 19\n        const val SOURCE_APP_SHORTCUT_RANDOM = 20\n        const val SOURCE_APP_SHORTCUT_CONTINUE_READING = 21\n        const val SOURCE_FEED_MOST_READ_ACTIVITY = 22\n        const val SOURCE_ON_THIS_DAY_CARD = 23\n        const val SOURCE_ON_THIS_DAY_ACTIVITY = 24\n        const val SOURCE_NOTIFICATION = 25\n        const val SOURCE_NOTIFICATION_SYSTEM = 26\n        const val SOURCE_EDIT_DESCRIPTION = 28\n        const val SOURCE_WIDGET = 29\n        const val SOURCE_SUGGESTED_EDITS = 30\n        const val SOURCE_TALK_TOPIC = 31\n        const val SOURCE_WATCHLIST = 32\n        const val SOURCE_EDIT_DIFF_DETAILS = 33\n        const val SOURCE_ERROR = 34\n        const val SOURCE_EDIT_HISTORY = 35\n        const val SOURCE_CATEGORY = 36\n        const val SOURCE_ARCHIVED_TALK = 37\n        const val SOURCE_USER_CONTRIB = 38\n        const val SOURCE_FILE_PAGE = 39\n        const val SOURCE_SINGLE_WEBVIEW = 40\n        const val SOURCE_SUGGESTED_EDITS_RECENT_EDITS = 41\n        const val SOURCE_FEED_PLACES = 42\n        const val SOURCE_ON_THIS_DAY_GAME = 43\n        const val SOURCE_RECOMMENDED_READING_LIST = 44\n        const val SOURCE_ACTIVITY_TAB = 45\n        const val SOURCE_FEED_ON_THIS_DAY = 46\n        const val SOURCE_FEED_CONTINUE_READING = 47\n        const val SOURCE_FEED_INTERESTS = 48\n        const val SOURCE_FEED_DID_YOU_KNOW = 49\n        const val SOURCE_ACTIVITY_DID_YOU_KNOW = 50\n        const val SOURCE_FEED_NEW_WITHIN_TOPIC = 51\n        const val SOURCE_FEED_READ_ALOUD = 52\n        const val SOURCE_YEAR_IN_REVIEW = 53\n    }\n}","file":"app/src/main/java/org/wikipedia/history/HistoryEntry.kt","kind":"class","line":19,"members":{"SOURCE_ACTIVITY_DID_YOU_KNOW":[110,110],"SOURCE_ACTIVITY_TAB":[105,105],"SOURCE_APP_SHORTCUT_CONTINUE_READING":[82,82],"SOURCE_APP_SHORTCUT_RANDOM":[81,81],"SOURCE_ARCHIVED_TALK":[97,97],"SOURCE_CATEGORY":[96,96],"SOURCE_DISAMBIG":[72,72],"SOURCE_EDIT_DESCRIPTION":[88,88],"SOURCE_EDIT_DIFF_DETAILS":[93,93],"SOURCE_EDIT_HISTORY":[95,95],"SOURCE_ERROR":[94,94],"SOURCE_EXTERNAL_LINK":[66,66],"SOURCE_FEED_BECAUSE_YOU_READ":[74,74],"SOURCE_FEED_CONTINUE_READING":[107,107],"SOURCE_FEED_DID_YOU_KNOW":[109,109],"SOURCE_FEED_FEATURED":[76,76],"SOURCE_FEED_INTERESTS":[108,108],"SOURCE_FEED_MAIN_PAGE":[78,78],"SOURCE_FEED_MOST_READ":[75,75],"SOURCE_FEED_MOST_READ_ACTIVITY":[83,83],"SOURCE_FEED_NEW_WITHIN_TOPIC":[111,111],"SOURCE_FEED_ON_THIS_DAY":[106,106],"SOURCE_FEED_PLACES":[102,102],"SOURCE_FEED_RANDOM":[79,79],"SOURCE_FEED_READ_ALOUD":[112,112],"SOURCE_FILE_PAGE":[99,99],"SOURCE_GALLERY":[80,80],"SOURCE_HISTORY":[67,67],"SOURCE_INTERNAL_LINK":[65,65],"SOURCE_LANGUAGE_LINK":[68,68],"SOURCE_MAIN_PAGE":[70,70],"SOURCE_NEWS":[77,77],"SOURCE_NOTIFICATION":[86,86],"SOURCE_NOTIFICATION_SYSTEM":[87,87],"SOURCE_ON_THIS_DAY_ACTIVITY":[85,85],"SOURCE_ON_THIS_DAY_CARD":[84,84],"SOURCE_ON_THIS_DAY_GAME":[103,103],"SOURCE_PLACES":[71,71],"SOURCE_RANDOM":[69,69],"SOURCE_READING_LIST":[73,73],"SOURCE_RECOMMENDED_READING_LIST":[104,104],"SOURCE_SEARCH":[64,64],"SOURCE_SINGLE_WEBVIEW":[100,100],"SOURCE_SUGGESTED_EDITS":[90,90],"SOURCE_SUGGESTED_EDITS_RECENT_EDITS":[101,101],"SOURCE_TALK_TOPIC":[91,91],"SOURCE_USER_CONTRIB":[98,98],"SOURCE_WATCHLIST":[92,92],"SOURCE_WIDGET":[89,89],"SOURCE_YEAR_IN_REVIEW":[113,113],"apiTitle":[29,29],"authority":[27,27],"constructor":[37,41],"displayTitle":[30,30],"id":[31,31],"lang":[28,28],"namespace":[32,32],"pageTitle":[43,46],"prevId":[35,35],"referrer":[57,61],"source":[34,34],"timestamp":[33,33],"title":[48,55]},"supers":["Parcelable"]},"LinkHandler":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"]],"code":"abstract class LinkHandler(protected val context: Context) : JSEventListener, UrlHandlerWithText {\n    open fun onPageLinkClicked(anchor: String, linkText: String) {}\n    open fun onInternalLinkClicked(title: PageTitle) {}\n    open fun onMediaLinkClicked(title: PageTitle) {}\n    open fun onDiffLinkClicked(title: PageTitle, revisionId: Long) {}\n    abstract var wikiSite: WikiSite\n\n    // message from JS bridge:\n    override fun onMessage(messageType: String, messagePayload: JsonObject?) {\n        messagePayload?.let {\n            onUrlClick(UriUtil.decodeURL(it[\"href\"]?.jsonPrimitive?.content.orEmpty()),\n                it[\"title\"]?.jsonPrimitive?.content,\n                it[\"text\"]?.jsonPrimitive?.content.orEmpty())\n        }\n    }\n\n    override fun onUrlClick(url: String, titleString: String?, linkText: String) {\n        var href = url\n        if (href.startsWith(\"mailto:\")) {\n            val emailAddress = href.removePrefix(\"mailto:\")\n            FeedbackUtil.composeEmail(context, emailAddress = emailAddress)\n            return\n        }\n\n        if (href.startsWith(\"//\")) {\n            // for URLs without an explicit scheme, add our default scheme explicitly.\n            href = wikiSite.scheme() + \":\" + href\n        } else if (href.startsWith(\"./\")) {\n            href = href.replace(\"./\", \"/wiki/\")\n        }\n\n        // special: returned by page-library when clicking Read More items in the footer.\n        val eventLoggingParamIndex = href.indexOf(\"?event-logging-label\")\n        if (eventLoggingParamIndex > 0) {\n            href = href.substring(0, eventLoggingParamIndex)\n        }\n        var uri = href.toUri()\n        uri.fragment?.run {\n            if (contains(\"cite\")) {\n                onPageLinkClicked(this, linkText)\n                return@onUrlClick\n            }\n        }\n        val knownScheme = KNOWN_SCHEMES.any { href.startsWith(\"$it:\") }\n        if (!knownScheme) {\n            // for URLs without a known scheme, add our default scheme explicitly.\n            uri = uri.buildUpon()\n                    .scheme(wikiSite.scheme())\n                    .authority(wikiSite.authority())\n                    .path(href)\n                    .build()\n        }\n\n        // TODO: remove this after the endpoint supporting language variants\n        val convertedText = UriUtil.getTitleFromUrl(href)\n        var titleStr = titleString\n        if (convertedText != titleStr) {\n            titleStr = convertedText\n        }\n        var site = WikiSite(uri)\n        if (site.subdomain() == wikiSite.subdomain() && site.languageCode != wikiSite.languageCode) {\n            // override the languageCode from the parent WikiSite, in case it's a variant.\n            site = WikiSite(uri.authority!!, wikiSite.languageCode)\n        }\n        L.d(\"Link clicked was $uri\")\n        val supportedAuthority = uri.authority?.run { WikiSite.supportedAuthority(this) } == true\n        when {\n            uri.path?.run { matches((\"^${UriUtil.WIKI_REGEX}.*\").toRegex()) } == true && supportedAuthority -> {\n                val newTitle = if (titleStr.isEmpty()) {\n                    PageTitle.titleForInternalLink(uri.path, site)\n                } else PageTitle.withSeparateFragment(titleStr, uri.fragment, site)\n                if (newTitle.isFilePage) {\n                    onMediaLinkClicked(newTitle)\n                } else if (newTitle.isSpecial) {\n                    onExternalLinkClicked(uri)\n                } else {\n                    onInternalLinkClicked(newTitle)\n                }\n            }\n            !uri.fragment.isNullOrEmpty() && supportedAuthority -> {\n                onPageLinkClicked(uri.fragment!!, linkText)\n            }\n            !uri.getQueryParameter(\"title\").isNullOrEmpty() && !uri.getQueryParameter(\"diff\").isNullOrEmpty() && supportedAuthority -> {\n                val diffAttr = uri.getQueryParameter(\"diff\").orEmpty()\n                var diffRev = diffAttr.toLongOrNull() ?: -1\n                if (diffAttr == \"next\" || diffAttr == \"prev\") {\n                    diffRev = uri.getQueryParameter(\"oldid\")?.toLongOrNull() ?: -1\n                }\n                onDiffLinkClicked(PageTitle(uri.getQueryParameter(\"title\"), site), diffRev)\n            }\n            else -> {\n                onExternalLinkClicked(uri)\n            }\n        }\n    }\n\n    open fun onExternalLinkClicked(uri: Uri) {\n        if (uri.authority.orEmpty().contains(\"geohack\") && context is Activity) {\n            StringUtil.geoHackToLocation(uri.getQueryParameter(\"params\"))?.let {\n                context.startActivity(PlacesActivity.newIntent(context, null, it))\n                return\n            }\n        }\n        UriUtil.handleExternalLink(context, uri)\n    }\n\n    companion object {\n        private val KNOWN_SCHEMES = listOf(\"http\", \"https\", \"geo\", \"file\", \"content\")\n    }\n}","file":"app/src/main/java/org/wikipedia/page/LinkHandler.kt","kind":"class","line":18,"members":{"KNOWN_SCHEMES":[125,125],"context":[18,18],"onDiffLinkClicked":[22,22],"onExternalLinkClicked":[114,122],"onInternalLinkClicked":[20,20],"onMediaLinkClicked":[21,21],"onMessage":[25,32],"onPageLinkClicked":[19,19],"onUrlClick":[34,112],"wikiSite":[23,23]},"supers":["JSEventListener","UrlHandlerWithText"]},"LinkPreviewDialog":{"appearsIn":[["article","h-widgets","Screen \u00b7 view composition"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"]],"code":"class LinkPreviewDialog : ExtendedBottomSheetDialogFragment(), LinkPreviewErrorView.Callback, DialogInterface.OnDismissListener {\n    interface LoadPageCallback {\n        fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean)\n    }\n\n    interface DismissCallback {\n        fun onLinkPreviewDismiss()\n    }\n\n    private var _binding: DialogLinkPreviewBinding? = null\n    private val binding get() = _binding!!\n\n    private val loadPageCallback get() = getCallback(this, LoadPageCallback::class.java)\n    private val dismissCallback get() = getCallback(this, DismissCallback::class.java)\n\n    private var articleLinkPreviewInteractionEvent: ArticleLinkPreviewInteractionEvent? = null\n    private var overlayView: LinkPreviewOverlayView? = null\n    private var navigateSuccess = false\n    private val viewModel: LinkPreviewViewModel by viewModels()\n\n    private val menuListener = PopupMenu.OnMenuItemClickListener { item ->\n        return@OnMenuItemClickListener when (item.itemId) {\n            R.id.menu_link_preview_add_to_list -> {\n                showSaveArticleSheet()\n                true\n            }\n            R.id.menu_link_preview_share_page -> {\n                ShareUtil.shareText(requireContext(), viewModel.pageTitle)\n                true\n            }\n            R.id.menu_link_preview_watch -> {\n                sendPlacesEvent(\"watch_click\", \"detail_overflow_menu\")\n                viewModel.watchOrUnwatch(viewModel.isWatched)\n                true\n            }\n            R.id.menu_link_preview_open_in_new_tab -> {\n                sendPlacesEvent(\"new_tab_click\", \"detail_overflow_menu\")\n                goToLinkedPage(true)\n                true\n            }\n            R.id.menu_link_preview_copy_link -> {\n                sendPlacesEvent(\"copy_link_click\", \"detail_overflow_menu\")\n                ClipboardUtil.setPlainText(requireActivity(), text = viewModel.pageTitle.uri)\n                FeedbackUtil.showMessage(requireActivity(), R.string.address_copied)\n                dismiss()\n                true\n            }\n            R.id.menu_link_preview_view_on_map -> {\n                PlacesEvent.logAction(\"places_click\", \"article_preview_more_menu\")\n                viewModel.location?.let {\n                    startActivity(PlacesActivity.newIntent(requireContext(), viewModel.pageTitle, it))\n                }\n                dismiss()\n                true\n            }\n            R.id.menu_link_preview_get_directions -> {\n                sendPlacesEvent(\"directions_click\", \"detail_overflow_menu\")\n                viewModel.location?.let {\n                    GeoUtil.sendGeoIntent(requireActivity(), it, StringUtil.fromHtml(viewModel.pageTitle.displayText).toString())\n                }\n                true\n            }\n            else -> false\n        }\n    }\n\n    private fun sendPlacesEvent(action: String, activeInterface: String) {\n        if (viewModel.historyEntry.source == HistoryEntry.SOURCE_PLACES) {\n            PlacesEvent.logAction(action, activeInterface)\n        }\n    }\n\n    private val galleryViewListener = GalleryViewListener { view, thumbUrl, imageName ->\n        var options: ActivityOptionsCompat? = null\n        view.drawable?.let {\n            val hitInfo = JavaScriptActionHandler.ImageHitInfo(0f, 0f, it.intrinsicWidth.toFloat(), it.intrinsicHeight.toFloat(), thumbUrl)\n            GalleryActivity.setTransitionInfo(hitInfo)\n            view.transitionName = requireActivity().getString(R.string.transition_page_gallery)\n            options = ActivityOptionsCompat.makeSceneTransitionAnimation(requireActivity(), view, requireActivity().getString(R.string.transition_page_gallery))\n        }\n        requestGalleryLauncher.launch(GalleryActivity.newIntent(requireContext(), viewModel.pageTitle,\n            imageName, viewModel.pageTitle.wikiSite), options)\n    }\n\n    private val requestGalleryLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == GalleryActivity.ACTIVITY_RESULT_PAGE_SELECTED && it.data != null) {\n            startActivity(it.data!!)\n        }\n    }\n\n    private val requestStubArticleEditLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == EditHandler.RESULT_REFRESH_PAGE) {\n            overlayView?.let { overlay ->\n                FeedbackUtil.makeSnackbar(overlay.rootView, getString(R.string.stub_article_edit_saved_successfully))\n                    .setAnchorView(overlay.secondaryButtonView).show()\n            }\n        }\n    }\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = DialogLinkPreviewBinding.inflate(inflater, container, false)\n        binding.linkPreviewToolbar.setOnClickListener { goToLinkedPage(false) }\n        binding.linkPreviewOverflowButton.setOnClickListener {\n            setupOverflowMenu()\n        }\n        binding.linkPreviewEditButton.setOnClickListener {\n            viewModel.pageTitle.run {\n                requestStubArticleEditLauncher.launch(EditSectionActivity.newIntent(requireContext(), -1, null, this, Constants.InvokeSource.LINK_PREVIEW_MENU, null))\n            }\n        }\n        binding.root.setLayoutDirectionByLang(viewModel.pageTitle.wikiSite.languageCode)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.uiState.collect {\n                    when (it) {\n                        is LinkPreviewViewState.Loading -> {\n                            binding.linkPreviewProgress.visibility = View.VISIBLE\n                        }\n                        is LinkPreviewViewState.Error -> {\n                            renderErrorState(it.throwable)\n                        }\n                        is LinkPreviewViewState.Content -> {\n                            renderContentState(it.data)\n                        }\n                        is LinkPreviewViewState.Gallery -> {\n                            renderGalleryState(it)\n                        }\n                        is LinkPreviewViewState.Watch -> {\n                            WatchlistViewModel.showWatchlistSnackbar(requireActivity() as BaseActivity, requireActivity().supportFragmentManager, viewModel.pageTitle, it.data.first, it.data.second)\n                            dismiss()\n                        }\n                        is LinkPreviewViewState.Completed -> {\n                            binding.linkPreviewProgress.visibility = View.GONE\n                        }\n                    }\n                }\n            }\n        }\n        return binding.root\n    }\n\n    private fun setupOverflowMenu() {\n        val popupMenu = PopupMenu(requireActivity(), binding.linkPreviewOverflowButton)\n        popupMenu.inflate(R.menu.menu_link_preview)\n        popupMenu.menu.findItem(R.id.menu_link_preview_add_to_list).isVisible = !viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_share_page).isVisible = !viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_watch).isVisible = viewModel.fromPlaces && AccountUtil.isLoggedIn\n        popupMenu.menu.findItem(R.id.menu_link_preview_watch).title = getString(if (viewModel.isWatched) R.string.menu_page_unwatch else R.string.menu_page_watch)\n        popupMenu.menu.findItem(R.id.menu_link_preview_open_in_new_tab).isVisible = viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_view_on_map).isVisible = !viewModel.fromPlaces && viewModel.location != null\n        popupMenu.menu.findItem(R.id.menu_link_preview_get_directions).isVisible = viewModel.fromPlaces\n        popupMenu.setOnMenuItemClickListener(menuListener)\n        popupMenu.show()\n    }\n\n    private fun renderGalleryState(it: LinkPreviewViewState.Gallery) {\n        binding.linkPreviewThumbnailGallery.setGalleryList(it.data)\n        binding.linkPreviewThumbnailGallery.listener = galleryViewListener\n        binding.linkPreviewProgress.visibility = View.GONE\n    }\n\n    private fun renderContentState(summary: PageSummary) {\n        articleLinkPreviewInteractionEvent = ArticleLinkPreviewInteractionEvent(\n                viewModel.pageTitle.wikiSite.dbName(),\n                summary.pageId,\n                viewModel.historyEntry.source\n        )\n        articleLinkPreviewInteractionEvent?.logLinkClick()\n\n        binding.linkPreviewTitle.text = StringUtil.fromHtml(summary.displayTitle)\n        if (viewModel.fromPlaces) {\n            viewModel.location?.let { startLocation ->\n                viewModel.lastKnownLocation?.let { endLocation ->\n                    binding.linkPreviewDistance.isVisible = true\n                    binding.linkPreviewDistance.text = GeoUtil.getDistanceWithUnit(startLocation, endLocation, Locale.getDefault())\n                }\n            }\n        }\n        showPreview(LinkPreviewContents(summary, viewModel.pageTitle.wikiSite))\n    }\n\n    private fun renderErrorState(throwable: Throwable) {\n        L.e(throwable)\n        binding.linkPreviewTitle.text = StringUtil.fromHtml(viewModel.pageTitle.displayText)\n        showError(throwable)\n    }\n\n    override fun onResume() {\n        super.onResume()\n\n        val containerView = requireDialog().findViewById<ViewGroup>(android.R.id.content)\n        if (overlayView == null && containerView != null) {\n            LinkPreviewOverlayView(requireContext()).let {\n                overlayView = it\n                if (viewModel.fromPlaces) {\n                    val strings = requireContext().getStrings(viewModel.pageTitle, intArrayOf(R.string.link_preview_dialog_share_button, R.string.link_preview_dialog_save_button, R.string.link_preview_dialog_read_button))\n                    it.callback = OverlayViewPlacesCallback()\n                    it.setPrimaryButtonText(strings[R.string.link_preview_dialog_share_button])\n                    it.setSecondaryButtonText(strings[R.string.link_preview_dialog_save_button])\n                    it.setTertiaryButtonText(strings[R.string.link_preview_dialog_read_button])\n                } else {\n                    val strings = requireContext().getStrings(viewModel.pageTitle, intArrayOf(R.string.button_continue_to_talk_page, R.string.button_continue_to_article, R.string.menu_long_press_open_in_new_tab))\n                    it.callback = OverlayViewCallback()\n                    it.setPrimaryButtonText(strings[if (viewModel.pageTitle.namespace() === Namespace.TALK || viewModel.pageTitle.namespace() === Namespace.USER_TALK) R.string.button_continue_to_talk_page else R.string.button_continue_to_article])\n                    it.setSecondaryButtonText(strings[R.string.menu_long_press_open_in_new_tab])\n                    it.showTertiaryButton(false)\n                }\n                containerView.addView(it)\n\n                ViewCompat.setOnApplyWindowInsetsListener(it) { view, insets ->\n                    val systemWindowInsets = insets.getInsets(WindowInsetsCompat.Type.systemBars())\n                    view.updateLayoutParams<ViewGroup.MarginLayoutParams> { bottomMargin = systemWindowInsets.bottom }\n                    insets\n                }\n            }\n        }\n    }\n\n    override fun onDestroyView() {\n        binding.linkPreviewThumbnailGallery.listener = null\n        binding.linkPreviewToolbar.setOnClickListener(null)\n        binding.linkPreviewOverflowButton.setOnClickListener(null)\n        overlayView?.let {\n            it.callback = null\n            overlayView = null\n        }\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onDismiss(dialogInterface: DialogInterface) {\n        super.onDismiss(dialogInterface)\n        dismissCallback?.onLinkPreviewDismiss()\n        if (!navigateSuccess) {\n            articleLinkPreviewInteractionEvent?.logCancel()\n        }\n    }\n\n    override fun onAddToList() {\n        showSaveArticleSheet()\n    }\n\n    override fun onDismiss() {\n        dismiss()\n    }\n\n    private fun showSaveArticleSheet() {\n        SaveArticleSheetDialog.show(parentFragmentManager, viewModel.pageTitle)\n    }\n\n    private fun showPreview(contents: LinkPreviewContents) {\n        viewModel.loadGallery()\n        setPreviewContents(contents)\n    }\n\n    private fun showError(caught: Throwable?) {\n        binding.dialogLinkPreviewContainer.layoutTransition = null\n        binding.dialogLinkPreviewContainer.minimumHeight = 0\n        binding.linkPreviewProgress.visibility = View.GONE\n        binding.dialogLinkPreviewContentContainer.visibility = View.GONE\n        binding.dialogLinkPreviewErrorContainer.visibility = View.VISIBLE\n        binding.dialogLinkPreviewErrorContainer.callback = this\n        binding.dialogLinkPreviewErrorContainer.setError(caught, viewModel.pageTitle)\n        LinkPreviewErrorType[caught, viewModel.pageTitle].run {\n            overlayView?.let {\n                it.showSecondaryButton(false)\n                it.showTertiaryButton(false)\n                it.setPrimaryButtonText(resources.getString(buttonText))\n                it.callback = buttonAction(binding.dialogLinkPreviewErrorContainer)\n                if (this !== LinkPreviewErrorType.OFFLINE) {\n                    binding.linkPreviewToolbar.setOnClickListener(null)\n                    binding.linkPreviewOverflowButton.visibility = View.GONE\n                }\n            }\n        }\n    }\n\n    private fun setPreviewContents(contents: LinkPreviewContents) {\n        val editVisibility = contents.extract.isNullOrBlank() && contents.ns?.id == Namespace.MAIN.code()\n        binding.linkPreviewEditButton.isVisible = editVisibility\n        binding.linkPreviewThumbnailGallery.isVisible = !editVisibility\n\n        val extract = if (editVisibility) \"<i>\" + getString(R.string.link_preview_stub_placeholder_text) + \"</i>\" else contents.extract\n        binding.linkPreviewExtract.text = StringUtil.fromHtml(extract)\n\n        contents.title.thumbUrl?.let {\n            binding.linkPreviewThumbnail.visibility = View.VISIBLE\n            ViewUtil.loadImage(binding.linkPreviewThumbnail, it)\n        }\n        overlayView?.run {\n            if (!viewModel.fromPlaces) {\n                setPrimaryButtonText(\n                    requireContext().getString(\n                        viewModel.pageTitle,\n                        if (contents.isDisambiguation) R.string.button_continue_to_disambiguation\n                        else if (viewModel.pageTitle.namespace() === Namespace.TALK || viewModel.pageTitle.namespace() === Namespace.USER_TALK) R.string.button_continue_to_talk_page\n                        else R.string.button_continue_to_article\n                    )\n                )\n            } else if (viewModel.fromPlaces) {\n                setSecondaryButtonText(requireContext().getString(viewModel.pageTitle, if (viewModel.isInReadingList) R.string.link_preview_dialog_saved_button else R.string.link_preview_dialog_save_button))\n            }\n        }\n    }\n\n    private fun goToLinkedPage(inNewTab: Boolean) {\n        navigateSuccess = true\n        dialog?.dismiss()\n        loadPage(viewModel.pageTitle, viewModel.historyEntry, inNewTab)\n    }\n\n    private fun loadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        loadPageCallback.let {\n            if (it != null) {\n                it.onLinkPreviewLoadPage(title, entry, inNewTab)\n            } else {\n                requireActivity().startActivity(\n                    if (inNewTab) PageActivity.newIntentForNewTab(requireContext(), entry, entry.title)\n                    else PageActivity.newIntentForCurrentTab(requireContext(), entry, entry.title, false)\n                )\n            }\n        }\n    }\n\n    private inner class OverlayViewCallback : LinkPreviewOverlayView.Callback {\n        override fun onPrimaryClick() {\n            goToLinkedPage(false)\n        }\n\n        override fun onSecondaryClick() {\n            goToLinkedPage(true)\n        }\n\n        override fun onTertiaryClick() {\n            // ignore\n        }\n    }\n\n    private inner class OverlayViewPlacesCallback : LinkPreviewOverlayView.Callback {\n        override fun onPrimaryClick() {\n            sendPlacesEvent(\"share_click\", \"detail_toolbar\")\n            ShareUtil.shareText(requireContext(), viewModel.pageTitle)\n        }\n\n        override fun onSecondaryClick() {\n            overlayView?.let {\n                sendPlacesEvent(\"save_click\", \"detail_toolbar\")\n                showSaveArticleSheet()\n            }\n        }\n\n        override fun onTertiaryClick() {\n            sendPlacesEvent(\"read_click\", \"detail_toolbar\")\n            goToLinkedPage(false)\n        }\n    }\n\n    companion object {\n        const val ARG_ENTRY = \"entry\"\n        const val ARG_LOCATION = \"location\"\n        const val ARG_LAST_KNOWN_LOCATION = \"lastKnownLocation\"\n\n        fun newInstance(entry: HistoryEntry, location: Location? = null, lastKnownLocation: Location? = null): LinkPreviewDialog {\n            return LinkPreviewDialog().apply {\n                arguments = bundleOf(\n                    ARG_ENTRY to entry,\n                    ARG_LOCATION to location,\n                    ARG_LAST_KNOWN_LOCATION to lastKnownLocation\n                )\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/linkpreview/LinkPreviewDialog.kt","kind":"class","line":56,"members":{"ARG_ENTRY":[415,415],"ARG_LAST_KNOWN_LOCATION":[417,417],"ARG_LOCATION":[416,416],"DismissCallback":[61,63],"LoadPageCallback":[57,59],"OverlayViewCallback":[381,393],"OverlayViewPlacesCallback":[395,412],"_binding":[65,65],"articleLinkPreviewInteractionEvent":[71,71],"binding":[66,66],"dismissCallback":[69,69],"galleryViewListener":[128,138],"goToLinkedPage":[362,366],"loadPage":[368,379],"loadPageCallback":[68,68],"menuListener":[76,120],"navigateSuccess":[73,73],"newInstance":[419,427],"onAddToList":[295,297],"onCreateView":[155,196],"onDestroyView":[275,285],"onDismiss":[287,293],"onResume":[244,273],"overlayView":[72,72],"renderContentState":[218,236],"renderErrorState":[238,242],"renderGalleryState":[212,216],"requestGalleryLauncher":[140,144],"requestStubArticleEditLauncher":[146,153],"sendPlacesEvent":[122,126],"setPreviewContents":[334,360],"setupOverflowMenu":[198,210],"showError":[312,332],"showPreview":[307,310],"showSaveArticleSheet":[303,305],"viewModel":[74,74]},"supers":["ExtendedBottomSheetDialogFragment()","LinkPreviewErrorView.Callback","DialogInterface.OnDismissListener"]},"ObservableWebView":{"appearsIn":[["article","h-widgets","Screen \u00b7 view composition"]],"code":"class ObservableWebView : WebView {\n\n    fun interface OnClickListener {\n        fun onClick(x: Float, y: Float): Boolean\n    }\n\n    fun interface OnScrollChangeListener {\n        fun onScrollChanged(oldScrollY: Int, scrollY: Int, isHumanScroll: Boolean)\n    }\n\n    fun interface OnDownMotionEventListener {\n        fun onDownMotionEvent()\n    }\n\n    fun interface OnUpOrCancelMotionEventListener {\n        fun onUpOrCancelMotionEvent()\n    }\n\n    fun interface OnContentHeightChangedListener {\n        fun onContentHeightChanged(contentHeight: Int)\n    }\n    fun interface OnFastScrollListener {\n        fun onFastScroll()\n    }\n\n    private var onClickListeners: MutableList<OnClickListener> = ArrayList()\n    private var onScrollChangeListeners: MutableList<OnScrollChangeListener> = ArrayList()\n    private var onDownMotionEventListeners: MutableList<OnDownMotionEventListener> = ArrayList()\n    private var onUpOrCancelMotionEventListeners: MutableList<OnUpOrCancelMotionEventListener> = ArrayList()\n    private var onContentHeightChangedListeners: MutableList<OnContentHeightChangedListener> = ArrayList()\n    private var onFastScrollListener: OnFastScrollListener? = null\n    private var currentContentHeight = 0\n    private var lastScrollTime: Long = 0\n    private var totalAmountScrolled = 0\n    private var drawEventsWhileSwiping = 0\n    private var touchSlop = ViewConfiguration.get(context).scaledTouchSlop\n\n    var scrollEventsEnabled = true\n    var touchStartX = 0f\n        private set\n    var touchStartY = 0f\n        private set\n    var lastTouchX = 0f\n        private set\n    var lastTouchY = 0f\n        private set\n\n    constructor(context: Context) : super(context)\n    constructor(context: Context, attrs: AttributeSet? = null) : super(context, attrs)\n    constructor(context: Context, attrs: AttributeSet? = null, defStyle: Int) : super(context, attrs, defStyle)\n\n    fun addOnClickListener(onClickListener: OnClickListener) {\n        onClickListeners.add(onClickListener)\n    }\n\n    fun addOnScrollChangeListener(onScrollChangeListener: OnScrollChangeListener) {\n        onScrollChangeListeners.add(onScrollChangeListener)\n    }\n\n    fun addOnDownMotionEventListener(onDownMotionEventListener: OnDownMotionEventListener) {\n        onDownMotionEventListeners.add(onDownMotionEventListener)\n    }\n\n    fun addOnUpOrCancelMotionEventListener(onUpOrCancelMotionEventListener: OnUpOrCancelMotionEventListener) {\n        onUpOrCancelMotionEventListeners.add(onUpOrCancelMotionEventListener)\n    }\n\n    fun addOnContentHeightChangedListener(onContentHeightChangedListener: OnContentHeightChangedListener) {\n        onContentHeightChangedListeners.add(onContentHeightChangedListener)\n    }\n\n    fun clearAllListeners() {\n        onClickListeners.clear()\n        onScrollChangeListeners.clear()\n        onDownMotionEventListeners.clear()\n        onUpOrCancelMotionEventListeners.clear()\n        onContentHeightChangedListeners.clear()\n        onFastScrollListener = null\n    }\n\n    override fun onScrollChanged(left: Int, top: Int, oldLeft: Int, oldTop: Int) {\n        super.onScrollChanged(left, top, oldLeft, oldTop)\n        val isHumanScroll = abs(top - oldTop) < MAX_HUMAN_SCROLL\n        if (scrollEventsEnabled) {\n            onScrollChangeListeners.forEach {\n                it.onScrollChanged(oldTop, top, isHumanScroll)\n            }\n        }\n        if (!isHumanScroll) {\n            return\n        }\n        totalAmountScrolled += top - oldTop\n        if (abs(totalAmountScrolled) > FAST_SCROLL_THRESHOLD &&\n                onFastScrollListener != null) {\n            onFastScrollListener!!.onFastScroll()\n            totalAmountScrolled = 0\n        }\n        lastScrollTime = System.currentTimeMillis()\n    }\n\n    @SuppressLint(\"ClickableViewAccessibility\")\n    override fun onTouchEvent(event: MotionEvent): Boolean {\n        if (event.buttonState == MotionEvent.BUTTON_SECONDARY &&\n                event.actionMasked == MotionEvent.ACTION_DOWN) {\n            handleMouseRightClick(event.x, event.y)\n            return true\n        }\n        lastTouchX = event.x\n        lastTouchY = event.y\n        when (event.actionMasked) {\n            MotionEvent.ACTION_DOWN -> {\n                onDownMotionEventListeners.forEach {\n                    it.onDownMotionEvent()\n                }\n                if (System.currentTimeMillis() - lastScrollTime > MAX_MILLIS_BETWEEN_SCROLLS) {\n                    totalAmountScrolled = 0\n                }\n                touchStartX = event.x\n                touchStartY = event.y\n                drawEventsWhileSwiping = 0\n            }\n            MotionEvent.ACTION_UP -> {\n                if (abs(event.x - touchStartX) <= touchSlop &&\n                        abs(event.y - touchStartY) <= touchSlop) {\n                    // Fire a click event, but only if the hit test doesn't land on a hyperlink\n                    // (i.e. only if the user clicks on whitespace or plain text in the WebView),\n                    // since link clicks will already be passed to the LinkHandler separately.\n                    if (hitTestResult.type == HitTestResult.UNKNOWN_TYPE) {\n                        if (onClickListeners.any { it.onClick(event.x, event.y) }) {\n                            return true\n                        }\n                    }\n                }\n                drawEventsWhileSwiping = 0\n                onUpOrCancelMotionEventListeners.forEach {\n                    it.onUpOrCancelMotionEvent()\n                }\n                drawEventsWhileSwiping = 0\n            }\n            MotionEvent.ACTION_CANCEL -> {\n                onUpOrCancelMotionEventListeners.forEach {\n                    it.onUpOrCancelMotionEvent()\n                }\n                drawEventsWhileSwiping = 0\n            }\n            else -> { }\n        }\n        return super.onTouchEvent(event)\n    }\n\n    private fun handleMouseRightClick(x: Float, y: Float) {\n        val eventTimeTravelMillis = 1000\n        post {\n            dispatchTouchEvent(MotionEvent.obtain(SystemClock.uptimeMillis(),\n                    SystemClock.uptimeMillis() + eventTimeTravelMillis,\n                    MotionEvent.ACTION_DOWN, x, y, 0))\n        }\n    }\n\n    override fun onDraw(canvas: Canvas) {\n        super.onDraw(canvas)\n        if (isInEditMode) {\n            return\n        }\n        drawEventsWhileSwiping++\n        if (drawEventsWhileSwiping > SWIPE_DRAW_TOLERANCE) {\n            setChildViewScrolled()\n        }\n        if (currentContentHeight != contentHeight) {\n            currentContentHeight = contentHeight\n            onContentHeightChangedListeners.forEach {\n                it.onContentHeightChanged(currentContentHeight)\n            }\n        }\n        FlowEventBus.post(INVALIDATE_EVENT)\n    }\n\n    companion object {\n        private val INVALIDATE_EVENT = WebViewInvalidateEvent()\n        private val FAST_SCROLL_THRESHOLD = (1000 * densityScalar).toInt()\n        private val MAX_HUMAN_SCROLL = (500 * densityScalar).toInt()\n        private const val MAX_MILLIS_BETWEEN_SCROLLS = 500\n        private const val SWIPE_DRAW_TOLERANCE = 4\n    }\n}","file":"app/src/main/java/org/wikipedia/views/ObservableWebView.kt","kind":"class","line":18,"members":{"FAST_SCROLL_THRESHOLD":[197,197],"INVALIDATE_EVENT":[196,196],"MAX_HUMAN_SCROLL":[198,198],"MAX_MILLIS_BETWEEN_SCROLLS":[199,199],"OnClickListener":[20,22],"OnContentHeightChangedListener":[36,38],"OnDownMotionEventListener":[28,30],"OnFastScrollListener":[39,41],"OnScrollChangeListener":[24,26],"OnUpOrCancelMotionEventListener":[32,34],"SWIPE_DRAW_TOLERANCE":[200,200],"addOnClickListener":[69,71],"addOnContentHeightChangedListener":[85,87],"addOnDownMotionEventListener":[77,79],"addOnScrollChangeListener":[73,75],"addOnUpOrCancelMotionEventListener":[81,83],"clearAllListeners":[89,96],"constructor":[65,65],"currentContentHeight":[49,49],"drawEventsWhileSwiping":[52,52],"handleMouseRightClick":[168,175],"lastScrollTime":[50,50],"lastTouchX":[60,60],"lastTouchY":[62,62],"onClickListeners":[43,43],"onContentHeightChangedListeners":[47,47],"onDownMotionEventListeners":[45,45],"onDraw":[177,193],"onFastScrollListener":[48,48],"onScrollChangeListeners":[44,44],"onScrollChanged":[98,116],"onTouchEvent":[118,166],"onUpOrCancelMotionEventListeners":[46,46],"scrollEventsEnabled":[55,55],"totalAmountScrolled":[51,51],"touchSlop":[53,53],"touchStartX":[56,56],"touchStartY":[58,58]},"shot":"shots/code/ObservableWebView.jpg","supers":["WebView"]},"PageActionItem":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"]],"code":"@Suppress(\"unused\")\nenum class PageActionItem constructor(val id: Int,\n                                      val viewId: Int,\n                                      @StringRes val titleResId: Int,\n                                      @DrawableRes val iconResId: Int = R.drawable.ic_settings_black_24dp,\n                                      val isAvailableOnMobileWeb: Boolean = true,\n                                      val isExternalLink: Boolean = false) : EnumCode {\n    // TODO: Need to add the newly added item to the default const lists below\n    SAVE(0, R.id.page_save, R.string.article_menu_bar_save_button, R.drawable.ic_bookmark_border_white_24dp, false) {\n        override fun select(cb: Callback) {\n            cb.onSaveSelected()\n        }\n    },\n    LANGUAGE(1, R.id.page_language, R.string.article_menu_bar_language_button, R.drawable.ic_translate_white_24dp, false) {\n        override fun select(cb: Callback) {\n            cb.onLanguageSelected()\n        }\n    },\n    FIND_IN_ARTICLE(2, R.id.page_find_in_article, R.string.menu_page_find_in_page, R.drawable.ic_find_in_page_24px) {\n        override fun select(cb: Callback) {\n            cb.onFindInArticleSelected()\n        }\n    },\n    THEME(3, R.id.page_theme, R.string.article_menu_bar_theme_button, R.drawable.ic_icon_format_size, false) {\n        override fun select(cb: Callback) {\n            cb.onThemeSelected()\n        }\n    },\n    CONTENTS(4, R.id.page_contents, R.string.article_menu_bar_contents_button, R.drawable.ic_icon_list, false) {\n        override fun select(cb: Callback) {\n            cb.onContentsSelected()\n        }\n    },\n    SHARE(5, R.id.page_share, R.string.menu_page_article_share, R.drawable.ic_share) {\n        override fun select(cb: Callback) {\n            cb.onShareSelected()\n        }\n    },\n    ADD_TO_WATCHLIST(6, R.id.page_watch, R.string.menu_page_watch, R.drawable.ic_baseline_star_outline_24, false) {\n        override fun select(cb: Callback) {\n            cb.onAddToWatchlistSelected()\n        }\n    },\n    VIEW_TALK_PAGE(7, R.id.page_view_talk_page, R.string.menu_page_talk_page, R.drawable.ic_icon_speech_bubbles_ooui_ltr) {\n        override fun select(cb: Callback) {\n            cb.onViewTalkPageSelected()\n        }\n    },\n    VIEW_EDIT_HISTORY(8, R.id.page_view_edit_history, R.string.menu_page_edit_history, R.drawable.ic_icon_revision_history_apps, true) {\n        override fun select(cb: Callback) {\n            cb.onViewEditHistorySelected()\n        }\n    },\n    NEW_TAB(9, R.id.page_new_tab, R.string.menu_new_tab, R.drawable.ic_add_gray_white_24dp) {\n        override fun select(cb: Callback) {\n            cb.onNewTabSelected()\n        }\n    },\n    HOME(10, R.id.page_home, R.string.home, R.drawable.ic_home_filled_24dp) {\n        override fun select(cb: Callback) {\n            cb.onHomeSelected()\n        }\n    },\n    CATEGORIES(11, R.id.page_categories, R.string.action_item_categories, R.drawable.ic_category_black_24dp) {\n        override fun select(cb: Callback) {\n            cb.onCategoriesSelected()\n        }\n    },\n    EDIT_ARTICLE(12, R.id.page_edit_article, R.string.menu_edit_article, R.drawable.ic_mode_edit_white_24dp) {\n        override fun select(cb: Callback) {\n            cb.onEditArticleSelected()\n        }\n    },\n    VIEW_ON_MAP(13, R.id.page_view_on_map, R.string.action_item_view_on_map, R.drawable.baseline_location_on_24, false) {\n        override fun select(cb: Callback) {\n            cb.onViewOnMapSelected()\n        }\n    };\n\n    abstract fun select(cb: Callback)\n\n    override fun code(): Int {\n        // This enumeration is not marshalled so tying declaration order to presentation order is\n        // convenient and consistent.\n        return ordinal\n    }\n\n    interface Callback {\n        fun onSaveSelected()\n        fun onLanguageSelected()\n        fun onFindInArticleSelected()\n        fun onThemeSelected()\n        fun onContentsSelected()\n        fun onShareSelected()\n        fun onAddToWatchlistSelected()\n        fun onViewTalkPageSelected()\n        fun onViewEditHistorySelected()\n        fun onNewTabSelected()\n        fun onHomeSelected()\n        fun onCategoriesSelected()\n        fun onEditArticleSelected()\n        fun onViewOnMapSelected()\n        fun forwardClick()\n    }\n\n    companion object {\n        val DEFAULT_TOOLBAR_LIST = listOf(SAVE, LANGUAGE, FIND_IN_ARTICLE, THEME, CONTENTS).map { it.id }\n        val DEFAULT_OVERFLOW_MENU_LIST = listOf(SHARE, ADD_TO_WATCHLIST, VIEW_TALK_PAGE, VIEW_EDIT_HISTORY, VIEW_ON_MAP, NEW_TAB, HOME, CATEGORIES, EDIT_ARTICLE).map { it.id }\n\n        fun find(id: Int): PageActionItem {\n            return entries.find { id == it.id || id == it.viewId } ?: entries[0]\n        }\n\n        @DrawableRes\n        fun watchlistIcon(isWatched: Boolean, hasWatchlistExpiry: Boolean): Int {\n            return if (isWatched && !hasWatchlistExpiry) {\n                R.drawable.ic_star_24\n            } else if (!isWatched) {\n                R.drawable.ic_baseline_star_outline_24\n            } else {\n                R.drawable.ic_baseline_star_half_24\n            }\n        }\n\n        @DrawableRes\n        fun readingListIcon(pageSaved: Boolean): Int {\n            return if (pageSaved) R.drawable.ic_bookmark_white_24dp else R.drawable.ic_bookmark_border_white_24dp\n        }\n\n        @DrawableRes\n        fun editArticleIcon(isProtected: Boolean): Int {\n            return if (isProtected) R.drawable.ic_edit_pencil_locked else R.drawable.ic_mode_edit_white_24dp\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/action/PageActionItem.kt","kind":"enum","line":8,"members":{"ADD_TO_WATCHLIST":[46,50],"CATEGORIES":[71,75],"CONTENTS":[36,40],"Callback":[95,111],"DEFAULT_OVERFLOW_MENU_LIST":[115,115],"DEFAULT_TOOLBAR_LIST":[114,114],"EDIT_ARTICLE":[76,80],"FIND_IN_ARTICLE":[26,30],"HOME":[66,70],"LANGUAGE":[21,25],"NEW_TAB":[61,65],"SAVE":[15,20],"SHARE":[41,45],"THEME":[31,35],"VIEW_EDIT_HISTORY":[56,60],"VIEW_ON_MAP":[81,85],"VIEW_TALK_PAGE":[51,55],"code":[89,93],"editArticleIcon":[137,140],"find":[117,119],"iconResId":[12,12],"id":[9,9],"isAvailableOnMobileWeb":[13,13],"isExternalLink":[14,14],"readingListIcon":[132,135],"select":[87,87],"titleResId":[11,11],"viewId":[10,10],"watchlistIcon":[121,130]},"supers":["EnumCode"]},"PageActionTabLayout":{"appearsIn":[["article","h-widgets","Screen \u00b7 view composition"]],"code":"class PageActionTabLayout constructor(context: Context, attrs: AttributeSet? = null) : ConfigurableTabLayout(context, attrs) {\n\n    lateinit var callback: PageActionItem.Callback\n\n    init {\n        update()\n    }\n\n    fun update() {\n        removeAllViews()\n        val typeface = Typeface.create(\"sans-serif-medium\", Typeface.NORMAL)\n        val tintColor = ResourceUtil.getThemedColorStateList(context, R.attr.primary_color)\n        val backgroundSource = ResourceUtil.getThemedAttributeId(context, androidx.appcompat.R.attr.selectableItemBackgroundBorderless)\n        Prefs.customizeToolbarOrder.forEach {\n            val view = MaterialTextView(context)\n            view.gravity = Gravity.CENTER\n            view.setPadding(DimenUtil.roundedDpToPx(2f), DimenUtil.roundedDpToPx(12f), DimenUtil.roundedDpToPx(2f), 0)\n            view.setBackgroundResource(backgroundSource)\n            view.setTextColor(tintColor)\n            view.textAlignment = TEXT_ALIGNMENT_CENTER\n            view.setTypeface(typeface, Typeface.NORMAL)\n            view.setTextSize(TypedValue.COMPLEX_UNIT_PX, resources.getDimension(R.dimen.bottom_nav_label_text_size))\n            view.maxLines = 2\n            view.ellipsize = TextUtils.TruncateAt.END\n\n            val item = PageActionItem.find(it)\n            view.id = item.viewId\n            view.text = context.getString(item.titleResId)\n            view.contentDescription = view.text\n            FeedbackUtil.setButtonTooltip(view)\n            TextViewCompat.setCompoundDrawableTintList(view, tintColor)\n            view.setCompoundDrawablesWithIntrinsicBounds(0, item.iconResId, 0, 0)\n            view.compoundDrawablePadding = -DimenUtil.roundedDpToPx(4f)\n            view.setOnClickListener { v ->\n                if (isEnabled(v)) {\n                    item.select(callback)\n                }\n            }\n            view.isFocusable = true\n            addView(view, LayoutParams(0, LayoutParams.MATCH_PARENT, 1.0f))\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageActionTabLayout.kt","kind":"class","line":19,"members":{"attrs":[19,19],"callback":[21,21],"context":[19,19],"update":[27,60]},"supers":["ConfigurableTabLayout(context, attrs)"]},"PageActivity":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-widgets","Screen \u00b7 view composition"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class PageActivity : BaseActivity(), PageFragment.Callback, LinkPreviewDialog.LoadPageCallback, FrameLayoutNavMenuTriggerer.Callback {\n\n    enum class TabPosition {\n        CURRENT_TAB, CURRENT_TAB_SQUASH, NEW_TAB_BACKGROUND, NEW_TAB_FOREGROUND, EXISTING_TAB\n    }\n\n    lateinit var binding: ActivityPageBinding\n    private lateinit var toolbarHideHandler: ViewHideHandler\n    private lateinit var pageFragment: PageFragment\n    private lateinit var app: WikipediaApp\n    private var hasTransitionAnimation = false\n    private var wasTransitionShown = false\n    private val currentActionModes = mutableSetOf<ActionMode>()\n    private val isCabOpen get() = currentActionModes.isNotEmpty()\n    private var exclusiveTooltipRunnable: Runnable? = null\n    private var isTooltipShowing = false\n    private val semanticSearchFeedbackViewModel: SemanticSearchArticleFeedbackViewModel by viewModels()\n    private var semanticSearchFeedbackJob: Job? = null\n\n    private val requestEditSectionLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == EditHandler.RESULT_REFRESH_PAGE) {\n            FeedbackUtil.makeSnackbar(this, getString(R.string.edit_saved_successfully))\n                .addCallback(object : Snackbar.Callback() {\n                    override fun onDismissed(transientBottomBar: Snackbar, @DismissEvent event: Int) {\n                        if (!isDestroyed) {\n                            AccountUtil.maybeShowTempAccountWelcome(this@PageActivity)\n                        }\n                    }\n                }).show()\n\n            // and reload the page...\n            pageFragment.refreshPage()\n        }\n    }\n\n    private val requestHandleIntentLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == LangLinksActivity.ACTIVITY_RESULT_LANGLINK_SELECT || it.resultCode == GalleryActivity.ACTIVITY_RESULT_PAGE_SELECTED) {\n            it.data?.let {\n                binding.pageToolbarContainer.post { handleIntent(it) }\n            }\n        }\n    }\n\n    private val requestGalleryEditLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == GalleryActivity.ACTIVITY_RESULT_IMAGE_CAPTION_ADDED || it.resultCode == GalleryActivity.ACTIVITY_RESULT_IMAGE_TAGS_ADDED) {\n            pageFragment.reloadFromBackstack()\n        }\n    }\n\n    private val requestBrowseTabLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (app.tabCount == 0 && it.resultCode != TabActivity.RESULT_NEW_TAB) {\n            // They browsed the tabs and cleared all of them, without wanting to open a new tab.\n            finish()\n            return@registerForActivityResult\n        }\n        if (it.resultCode == TabActivity.RESULT_NEW_TAB) {\n            loadMainPage(TabPosition.NEW_TAB_FOREGROUND)\n            animateTabsButton()\n        } else if (it.resultCode == TabActivity.RESULT_LOAD_FROM_BACKSTACK) {\n            pageFragment.reloadFromBackstack(false)\n        }\n    }\n\n    private val requestSuggestedEditsLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK || it.resultCode == DescriptionEditSuccessActivity.RESULT_OK_FROM_EDIT_SUCCESS) {\n            pageFragment.refreshPage()\n            val data = it.data\n            val editLanguage = pageFragment.leadImageEditLang.orEmpty().ifEmpty { app.languageState.appLanguageCode }\n            val action = if (data != null && data.hasExtra(Constants.INTENT_EXTRA_ACTION))\n                data.getSerializableExtra(Constants.INTENT_EXTRA_ACTION) as DescriptionEditActivity.Action?\n            else null\n\n            SuggestedEditsSnackbars.show(this, action, it.resultCode != DescriptionEditSuccessActivity.RESULT_OK_FROM_EDIT_SUCCESS,\n                editLanguage, action !== DescriptionEditActivity.Action.ADD_DESCRIPTION && action !== DescriptionEditActivity.Action.TRANSLATE_DESCRIPTION) {\n                pageFragment.page?.leadImageName?.let { imageName ->\n                    val wikiSite = WikiSite.forLanguageCode(pageFragment.leadImageEditLang.orEmpty().ifEmpty { app.appOrSystemLanguageCode })\n                    val imageTitle = PageTitle(\"File:${StringUtil.removeNamespace(imageName)}\", wikiSite)\n                    if (action === DescriptionEditActivity.Action.ADD_IMAGE_TAGS) {\n                        startActivity(FilePageActivity.newIntent(this, imageTitle))\n                    } else if (action === DescriptionEditActivity.Action.ADD_CAPTION || action === DescriptionEditActivity.Action.TRANSLATE_CAPTION) {\n                        pageFragment.title?.let { pageTitle ->\n                            startActivity(GalleryActivity.newIntent(this, pageTitle, imageTitle.prefixedText, wikiSite))\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    public override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        if (!DeviceUtil.assertAppContext(this)) {\n            return\n        }\n\n        app = WikipediaApp.instance\n\n        PreferenceManager.setDefaultValues(this, R.xml.preferences, false)\n        binding = ActivityPageBinding.inflate(layoutInflater)\n        setContentView(binding.root)\n\n        onBackPressedDispatcher.addCallback(this, onBackPressedCallback)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        is ChangeTextSizeEvent -> {\n                            pageFragment.updateFontSize()\n                        }\n                        is ArticleSavedOrDeletedEvent -> {\n                            pageFragment.title?.run {\n                                if (event.pages.any { it.apiTitle == prefixedText && it.lang == wikiSite.languageCode }) {\n                                    pageFragment.updateBookmarkAndMenuOptionsFromDao()\n                                }\n                            }\n                        }\n                        is LoggedInEvent -> {\n                            updateForLoginState()\n                            FeedbackUtil.showMessage(this@PageActivity, R.string.login_success_toast)\n                        }\n                        is LoggedOutEvent -> {\n                            updateForLoginState()\n                        }\n                    }\n                }\n            }\n        }\n\n        updateProgressBar(false)\n        pageFragment = supportFragmentManager.findFragmentById(R.id.page_fragment) as PageFragment\n\n        // Toolbar setup\n        setSupportActionBar(binding.pageToolbar)\n        clearActionBarTitle()\n        supportActionBar?.setDisplayHomeAsUpEnabled(true)\n\n        binding.pageToolbarButtonSearch.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logSearchWikipediaClick()\n            val articleTitle = if (pageFragment.title?.namespace() == Namespace.MAIN) pageFragment.title?.displayText else null\n            startActivity(SearchActivity.newIntent(\n                context = this@PageActivity,\n                source = InvokeSource.TOOLBAR,\n                query = null,\n                title = articleTitle))\n        }\n        binding.pageToolbarButtonTabs.updateTabCount(false)\n        binding.pageToolbarButtonTabs.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logTabsClick()\n            requestBrowseTabLauncher.launch(TabActivity.newIntentFromPageActivity(this))\n        }\n        toolbarHideHandler = ViewHideHandler(binding.pageToolbarContainer, null, Gravity.TOP) { isTooltipShowing }\n        FeedbackUtil.setButtonTooltip(binding.pageToolbarButtonNotifications, binding.pageToolbarButtonTabs, binding.pageToolbarButtonShowOverflowMenu)\n        binding.pageToolbarButtonShowOverflowMenu.setOnClickListener {\n            pageFragment.showOverflowMenu(it)\n            pageFragment.articleInteractionEvent?.logMoreClick()\n            Prefs.showOneTimeCustomizeToolbarTooltip = false\n        }\n\n        binding.pageToolbarButtonNotifications.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logNotificationClick()\n            if (AccountUtil.isLoggedIn) {\n                startActivity(NotificationActivity.newIntent(this@PageActivity))\n            } else if (AnonymousNotificationHelper.isWithinAnonNotificationTime() && !Prefs.lastAnonNotificationLang.isNullOrEmpty()) {\n                val wikiSite = WikiSite.forLanguageCode(Prefs.lastAnonNotificationLang!!)\n                startActivity(TalkTopicsActivity.newIntent(this@PageActivity,\n                PageTitle(UserTalkAliasData.valueFor(wikiSite.languageCode) + \":\" + Prefs.lastAnonUserWithMessages, wikiSite), InvokeSource.PAGE_ACTIVITY))\n            }\n        }\n\n        // Navigation setup\n        binding.navigationDrawer.setScrimColor(Color.TRANSPARENT)\n        binding.containerWithNavTrigger.callback = this\n        ViewCompat.setOnApplyWindowInsetsListener(binding.navigationDrawer) { view, insets ->\n            val insets = insets.getInsets(WindowInsetsCompat.Type.systemBars())\n            view.updateLayoutParams<MarginLayoutParams> {\n                topMargin = insets.top\n                leftMargin = insets.left\n                bottomMargin = insets.bottom\n                rightMargin = insets.right\n            }\n            WindowInsetsCompat.CONSUMED\n        }\n\n        // WikiArticleCard setup\n        hasTransitionAnimation = intent.getBooleanExtra(Constants.INTENT_EXTRA_HAS_TRANSITION_ANIM, false)\n        binding.wikiArticleCardView.visibility = if (hasTransitionAnimation) View.VISIBLE else View.GONE\n\n        val languageChanged = savedInstanceState?.let {\n            app.appOrSystemLanguageCode != savedInstanceState.getString(LANGUAGE_CODE_BUNDLE_KEY).orEmpty()\n        } ?: false\n\n        if (languageChanged) {\n            app.resetWikiSite()\n            loadMainPage(TabPosition.EXISTING_TAB)\n        }\n\n        if (savedInstanceState == null) {\n            // if there's no savedInstanceState, and we're not coming back from a Theme change,\n            // then we must have been launched with an Intent, so... handle it!\n            handleIntent(intent)\n        }\n        updateForLoginState()\n    }\n\n    override fun onStart() {\n        try {\n            super.onStart()\n        } catch (e: Exception) {\n            if (e.message.orEmpty().contains(EXCEPTION_MESSAGE_WEBVIEW, true) ||\n                ThrowableUtil.getInnermostThrowable(e).message.orEmpty().contains(EXCEPTION_MESSAGE_WEBVIEW, true)) {\n                // If the system failed to inflate our activity because of the WebView (which could\n                // be one of several types of exceptions), it likely means that the system WebView\n                // is in the process of being updated. In this case, show the user a message and\n                // bail immediately.\n                Toast.makeText(app, R.string.error_webview_updating, Toast.LENGTH_LONG).show()\n                finish()\n                return\n            }\n            throw e\n        }\n    }\n\n    override fun onPrepareOptionsMenu(menu: Menu): Boolean {\n        if (!isDestroyed) {\n            binding.pageToolbarButtonTabs.updateTabCount(false)\n        }\n        return false\n    }\n\n    override fun onOptionsItemSelected(item: MenuItem): Boolean {\n        return when (item.itemId) {\n            android.R.id.home -> {\n                if (app.haveMainActivity) {\n                    onBackPressedDispatcher.onBackPressed()\n                } else {\n                    pageFragment.goToMainActivity(tab = NavTab.HOME, tabExtra = Constants.INTENT_EXTRA_GO_TO_MAIN_TAB)\n                }\n                true\n            } else -> super.onOptionsItemSelected(item)\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        app.resetWikiSite()\n        updateNotificationsButton(false)\n        Prefs.temporaryWikitext = null\n    }\n\n    override fun onPause() {\n        if (isCabOpen) {\n            onPageCloseActionMode()\n        }\n        super.onPause()\n    }\n\n    override fun onSaveInstanceState(outState: Bundle) {\n        super.onSaveInstanceState(outState)\n        outState.putString(LANGUAGE_CODE_BUNDLE_KEY, app.appOrSystemLanguageCode)\n    }\n\n    override fun onActionModeStarted(mode: ActionMode) {\n        super.onActionModeStarted(mode)\n        if (!isCabOpen && mode.tag == null) {\n            modifyMenu(mode)\n            ViewUtil.setCloseButtonInActionMode(pageFragment.requireContext(), mode)\n            pageFragment.onActionModeShown(mode)\n        }\n        currentActionModes.add(mode)\n    }\n\n    override fun onActionModeFinished(mode: ActionMode) {\n        super.onActionModeFinished(mode)\n        currentActionModes.remove(mode)\n    }\n\n    override fun onDestroy() {\n        Prefs.hasVisitedArticlePage = true\n        if (isFinishing) {\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n        } else if (!isChangingConfigurations) {\n            // The view model is discarded along with this activity, so the pending prompt can't be resumed.\n            cancelSemanticSearchFeedback(FeedbackSuppression.SCREEN_COVERED)\n        }\n        super.onDestroy()\n    }\n\n    override fun onNewIntent(intent: Intent) {\n        super.onNewIntent(intent)\n        setIntent(intent)\n        handleIntent(intent)\n    }\n\n    private fun updateForLoginState() {\n        binding.pageToolbarButtonNotifications.isVisible = AccountUtil.isLoggedIn\n    }\n\n    private val onBackPressedCallback = object : OnBackPressedCallback(true) {\n        override fun handleOnBackPressed() {\n            if (isCabOpen) {\n                onPageCloseActionMode()\n                return\n            }\n            app.appSessionEvent.backPressed()\n            if (pageFragment.onBackPressed()) {\n                return\n            }\n\n            // If user enter PageActivity in portrait and leave in landscape,\n            // we should hide the transition animation view to prevent bad animation.\n            if (DimenUtil.isLandscape(this@PageActivity) || !hasTransitionAnimation) {\n                binding.wikiArticleCardView.visibility = View.GONE\n            } else {\n                binding.wikiArticleCardView.visibility = View.VISIBLE\n                binding.pageFragment.visibility = View.GONE\n            }\n            this.isEnabled = false\n            onBackPressedDispatcher.onBackPressed()\n        }\n    }\n\n    override fun onKeyDown(keyCode: Int, event: KeyEvent): Boolean {\n        if (event.isCtrlPressed && keyCode == KeyEvent.KEYCODE_F || !event.isCtrlPressed && keyCode == KeyEvent.KEYCODE_F3) {\n            pageFragment.showFindInPage()\n            return true\n        }\n        return super.onKeyDown(keyCode, event)\n    }\n\n    override fun onNavMenuSwipeRequest(gravity: Int) {\n        if (!isCabOpen && gravity == Gravity.END) {\n            pageFragment.articleInteractionEvent?.logTocSwipe()\n            pageFragment.sidePanelHandler.showToC()\n        }\n    }\n\n    override fun onPageLoadComplete() {\n        removeTransitionAnimState()\n        maybeShowThemeTooltip()\n        updateSearchHint()\n        lifecycleScope.launch {\n            ReadingChallengeWidgetRepository(this@PageActivity).updateOnArticleRead(LocalDate.now())\n        }\n        scheduleSemanticSearchFeedback()\n    }\n\n    private fun scheduleSemanticSearchFeedback() {\n        val pendingFeedback = semanticSearchFeedbackViewModel.semanticSearchFeedback ?: return\n        if (pageFragment.title != pendingFeedback.title) {\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n            return\n        }\n        if (semanticSearchFeedbackJob != null) {\n            return\n        }\n        val delayMillis = semanticSearchFeedbackViewModel.startCountdown()\n        semanticSearchFeedbackJob = lifecycleScope.launch {\n            delay(delayMillis.milliseconds)\n            val suppression = when {\n                pageFragment.title != pendingFeedback.title -> FeedbackSuppression.LEFT_ARTICLE\n                !lifecycle.currentState.isAtLeast(Lifecycle.State.RESUMED) ||\n                        ExclusiveBottomSheetPresenter.getCurrentBottomSheet(supportFragmentManager) != null ||\n                        ExclusiveBottomSheetPresenter.getCurrentBottomSheet(pageFragment.childFragmentManager) != null -> FeedbackSuppression.SCREEN_COVERED\n                isCabOpen || pageFragment.sidePanelHandler.isVisible -> FeedbackSuppression.STARTED_ACTIVITY\n                else -> null\n            }\n            if (suppression == null) {\n                ExclusiveBottomSheetPresenter.show(supportFragmentManager,\n                    SemanticSearchFeedbackDialog.newInstance(pendingFeedback.title.wikiSite.languageCode,\n                        pendingFeedback.searchId, pendingFeedback.funnel))\n            } else {\n                submitSemanticSearchFeedbackSuppressed(pendingFeedback, suppression)\n            }\n            semanticSearchFeedbackViewModel.clear()\n            semanticSearchFeedbackJob = null\n        }\n    }\n\n    private fun cancelSemanticSearchFeedback(suppression: FeedbackSuppression? = null) {\n        val pendingFeedback = semanticSearchFeedbackViewModel.semanticSearchFeedback\n        if (pendingFeedback != null && suppression != null) {\n            submitSemanticSearchFeedbackSuppressed(pendingFeedback, suppression)\n        }\n        semanticSearchFeedbackJob?.cancel()\n        semanticSearchFeedbackJob = null\n        semanticSearchFeedbackViewModel.clear()\n    }\n\n    private fun submitSemanticSearchFeedbackSuppressed(pendingFeedback: SemanticSearchFeedback, suppression: FeedbackSuppression) {\n        SemanticSearchFeedbackDialog.submitSuppressedEvent(\n            instrument = SemanticSearchFeedbackDialog.newInstrument(pendingFeedback.funnel, pendingFeedback.title.wikiSite),\n            actionSubtype = \"article_result\", suppression\n        )\n    }\n\n    override fun onPageDismissBottomSheet() {\n        ExclusiveBottomSheetPresenter.dismiss(supportFragmentManager)\n    }\n\n    override fun onPageInitWebView(v: ObservableWebView) {\n        toolbarHideHandler.setScrollView(v)\n    }\n\n    override fun onPageLoadPage(title: PageTitle, entry: HistoryEntry) {\n        loadPage(title, entry, TabPosition.CURRENT_TAB)\n    }\n\n    override fun onPageShowLinkPreview(entry: HistoryEntry) {\n        ExclusiveBottomSheetPresenter.show(supportFragmentManager, LinkPreviewDialog.newInstance(entry))\n    }\n\n    override fun onPageLoadMainPageInForegroundTab() {\n        loadMainPage(TabPosition.EXISTING_TAB)\n    }\n\n    override fun onPageUpdateProgressBar(visible: Boolean) {\n        updateProgressBar(visible)\n    }\n\n    override fun onPageStartSupportActionMode(callback: ActionMode.Callback) {\n        startActionMode(callback)\n    }\n\n    override fun onPageHideSoftKeyboard() {\n        DeviceUtil.hideSoftKeyboard(this)\n    }\n\n    override fun onPageWatchlistExpirySelect(expiry: WatchlistExpiry) {\n        pageFragment.updateWatchlistExpiry(expiry)\n    }\n\n    override fun onPageLoadError(title: PageTitle) {\n        supportActionBar?.title = title.displayText\n        removeTransitionAnimState()\n        cancelSemanticSearchFeedback()\n    }\n\n    override fun onPageLoadErrorBackPressed() {\n        finish()\n    }\n\n    override fun onPageSetToolbarElevationEnabled(enabled: Boolean) {\n        binding.pageToolbarContainer.elevation = DimenUtil.dpToPx(if (enabled) DimenUtil.getDimension(R.dimen.toolbar_default_elevation) else 0F)\n    }\n\n    override fun onPageCloseActionMode() {\n        val actionModesToFinish = HashSet(currentActionModes)\n        for (mode in actionModesToFinish) {\n            mode.finish()\n        }\n        currentActionModes.clear()\n    }\n\n    override fun onPageRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?) {\n        val isVisualEditorEnabled = RemoteConfig.config.androidv1?.visualEditorEnabled ?: false\n        val launchEditor = {\n            if (Prefs.editorModeChoice == EDITOR_CHOICE_VE && isVisualEditorEnabled) {\n                openVisualEditorInExternalBrowser(title, sectionId)\n            } else {\n                requestEditSectionLauncher.launch(EditSectionActivity.newIntent(this, sectionId, sectionAnchor, title, InvokeSource.PAGE_ACTIVITY, highlightText))\n            }\n        }\n        if (Prefs.editorModeChoiceShowDialog && isVisualEditorEnabled) {\n            showEditorChoiceDialog(this) { editorChoice, dontShowAgain ->\n                Prefs.editorModeChoice = editorChoice\n                Prefs.editorModeChoiceShowDialog = !dontShowAgain\n                launchEditor()\n            }\n        } else {\n            launchEditor()\n        }\n    }\n\n    private fun openVisualEditorInExternalBrowser(title: PageTitle, sectionId: Int) {\n        val appInstallId = WikipediaApp.instance.appInstallID\n        UriUtil.visitInExternalBrowser(this, title.getWebApiUrl(\"veaction=edit&section=$sectionId&returntoapp=1&appinstallid=$appInstallId\").toUri())\n    }\n\n    override fun onPageRequestLangLinks(title: PageTitle, historyEntryId: Long) {\n        requestHandleIntentLauncher.launch(LangLinksActivity.newIntent(this, title, historyEntryId))\n    }\n\n    override fun onPageRequestGallery(title: PageTitle, fileName: String, wikiSite: WikiSite, revision: Long, isLeadImage: Boolean, options: ActivityOptionsCompat?) {\n        if (isLeadImage) {\n            requestGalleryEditLauncher.launch(GalleryActivity.newIntent(this, title, fileName, title.wikiSite, revision), options)\n        } else {\n            requestHandleIntentLauncher.launch(GalleryActivity.newIntent(this, title, fileName, title.wikiSite, revision), options)\n        }\n    }\n\n    override fun onPageRequestEditDescription(text: String?, title: PageTitle, sourceSummary: PageSummaryForEdit?,\n                                              targetSummary: PageSummaryForEdit?, action: DescriptionEditActivity.Action, invokeSource: InvokeSource) {\n        requestSuggestedEditsLauncher.launch(DescriptionEditActivity.newIntent(this, title, text, sourceSummary, targetSummary, action, invokeSource))\n    }\n\n    override fun onPageRequestAddImageTags(mwQueryPage: MwQueryPage, invokeSource: InvokeSource) {\n        requestSuggestedEditsLauncher.launch(SuggestedEditsImageTagEditActivity.newIntent(this, mwQueryPage, invokeSource))\n    }\n\n    override fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        loadPage(title, entry, if (inNewTab) TabPosition.NEW_TAB_BACKGROUND else TabPosition.CURRENT_TAB)\n    }\n\n    private fun handleIntent(intent: Intent) {\n        if (intent.action == Intent.ACTION_MAIN && intent.categories?.contains(Intent.CATEGORY_LAUNCHER) == true) {\n            TestKitchenAdapter.client.getInstrument(\"apps-open\")\n                .submitInteraction(action = \"app_open\", actionSource = \"app_icon\")\n        }\n        if (Intent.ACTION_VIEW == intent.action && intent.data != null) {\n            var uri = intent.data!!\n\n            // Push back if the user is still in the Visual Editor flow.\n            uri.getQueryParameter(\"veaction\")?.let {\n                if (it == \"edit\") {\n                    val title = PageTitle.titleForUri(uri, WikiSite(uri))\n                    val sectionId = uri.getQueryParameter(\"section\")?.toIntOrNull() ?: 0\n                    // If the link is a VisualEditor edit link, then we should open it in an external browser.\n                    openVisualEditorInExternalBrowser(title, sectionId)\n                    return\n                }\n            }\n\n            TestKitchenAdapter.client.getInstrument(\"apps-open\")\n                .submitInteraction(action = \"app_open\", actionSource = \"external_link\")\n\n            if (uri.scheme == \"wikipedia\") {\n                uri = uri.buildUpon().scheme(WikiSite.DEFAULT_SCHEME).build()\n                uri.getQueryParameter(\"saved\")?.let {\n                    if (it == \"true\") {\n                        val revision = uri.getQueryParameter(\"revision\")?.toLongOrNull()\n                        if (revision != null && pageFragment.title != null) {\n                            lifecycleScope.launch(CoroutineExceptionHandler { _, t ->\n                                L.e(t)\n                            }) {\n                                EditSectionViewModel.retryUntilNewRevision(pageFragment.title!!, revision)\n                                pageFragment.refreshPage()\n                                FeedbackUtil.showMessage(this@PageActivity, R.string.edit_saved_successfully)\n                            }\n                        } else {\n                            binding.root.post {\n                                if (!isDestroyed) {\n                                    FeedbackUtil.showMessage(this, R.string.edit_saved_successfully)\n                                }\n                            }\n                        }\n                    } else {\n                        L.d(\"Edit abandoned.\")\n                    }\n                }\n            }\n\n            if (!ReleaseUtil.isPreBetaRelease && uri.scheme != null && uri.scheme == \"http\") {\n                // For external links, ensure that they're using https.\n                uri = uri.buildUpon().scheme(WikiSite.DEFAULT_SCHEME).build()\n            }\n            if (!Service.isWikimediaAuthority(uri.authority)) {\n                UriUtil.visitInExternalBrowser(this, uri)\n                finish()\n                return\n            }\n            val wiki = WikiSite(uri)\n            val title = PageTitle.titleForUri(uri, wiki)\n            val historyEntry = HistoryEntry(title, if (intent.hasExtra(Constants.INTENT_EXTRA_NOTIFICATION_ID))\n                HistoryEntry.SOURCE_NOTIFICATION_SYSTEM else HistoryEntry.SOURCE_EXTERNAL_LINK)\n            // Populate the referrer with the externally-referring URL, e.g. an external Browser URL, if present.\n            ActivityCompat.getReferrer(this)?.let { uri ->\n                historyEntry.referrer = uri.toString()\n            }\n            if (title.namespace() == Namespace.SPECIAL && title.prefixedText.startsWith(\"Special:ReadingLists\")) {\n                L.d(\"Received shareable reading lists\")\n                val encodedListFromParameter = uri.getQueryParameter(\"limport\")\n                Prefs.importReadingListsDialogShown = false\n                Prefs.receiveReadingListsData = encodedListFromParameter\n                startActivity(ReadingListActivity.newIntent(this, ReadingListMode.PREVIEW).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP))\n                finish()\n                return\n            }\n            // Special cases:\n            // If the subdomain of the URL is not a \"language\" subdomain as we expect, then\n            // bounce it out to an external browser. This can be links to the \"donate.\" or\n            // \"thankyou.\" subdomains, or the Wikiquote \"quote.\" subdomain, and possibly others.\n            val language = wiki.languageCode.lowercase(Locale.getDefault())\n            if (Constants.NON_LANGUAGE_SUBDOMAINS.contains(language) || (title.isSpecial && !title.isContributions)) {\n                // ...Except if the URL came as a result of a successful donation, in which case\n                // treat it differently:\n                if (language == \"thankyou\" && uri.getQueryParameter(\"order_id\") != null) {\n                    CampaignCollection.addDonationResult(fromWeb = true,\n                        amount = (uri.getQueryParameter(\"amount\"))?.toFloat() ?: 0f,\n                        currency = uri.getQueryParameter(\"currency\") ?: \"\",\n                        recurring = uri.getQueryParameter(\"recurring\") == \"1\")\n                    // Check if the donation started from the app, but completed via web, in which case\n                    // show it in a SingleWebViewActivity.\n                    val campaign = uri.getQueryParameter(\"wmf_campaign\")\n\n                    if (campaign != null && campaign == \"Android\") {\n                        var pageContentInfo = SingleWebViewActivity.PAGE_CONTENT_SOURCE_DONOR_EXPERIENCE\n                        YearInReviewViewModel.currentCampaignId?.let { campaignId ->\n                            TestKitchenAdapter.client.getInstrument(\"apps-year-in-review\")\n                                .submitInteraction(action = \"impression\", actionSource = \"webpay_processed\", actionContext = mapOf(\"campaign_id\" to campaignId))\n                            pageContentInfo = SingleWebViewActivity.PAGE_CONTENT_SOURCE_YIR\n                        } ?: run {\n                            DonorExperienceEvent.logAction(\"impression\", \"webpay_processed\", wiki.languageCode)\n                        }\n                        startActivity(SingleWebViewActivity.newIntent(this@PageActivity, uri.toString(),\n                            true, pageFragment.title, pageContentInfo))\n                        finish()\n                        return\n                    }\n                }\n                UriUtil.visitInExternalBrowser(this, uri)\n                finish()\n                return\n            }\n            loadPage(title, historyEntry, TabPosition.NEW_TAB_FOREGROUND)\n        } else if ((ACTION_LOAD_IN_NEW_TAB == intent.action || ACTION_LOAD_IN_CURRENT_TAB == intent.action ||\n                    ACTION_LOAD_IN_CURRENT_TAB_SQUASH == intent.action) && intent.hasExtra(EXTRA_HISTORYENTRY)) {\n            val title = intent.parcelableExtra<PageTitle>(Constants.ARG_TITLE)\n            val historyEntry = intent.parcelableExtra<HistoryEntry>(EXTRA_HISTORYENTRY)\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n            if (title != null && intent.getBooleanExtra(EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK, false)) {\n                semanticSearchFeedbackViewModel.setup(title,\n                    intent.getStringExtra(EXTRA_SEMANTIC_SEARCH_ID),\n                    intent.getSerializableExtra(EXTRA_SEMANTIC_SEARCH_FUNNEL) as Funnel?)\n            }\n            val highlightText = intent.getStringExtra(EXTRA_HIGHLIGHT_TEXT)\n            when (intent.action) {\n                ACTION_LOAD_IN_NEW_TAB -> loadPage(title, historyEntry, TabPosition.NEW_TAB_FOREGROUND)\n                ACTION_LOAD_IN_CURRENT_TAB -> loadPage(title, historyEntry, TabPosition.CURRENT_TAB, highlightText)\n                ACTION_LOAD_IN_CURRENT_TAB_SQUASH -> loadPage(title, historyEntry, TabPosition.CURRENT_TAB_SQUASH, highlightText)\n            }\n            intent.getStringExtra(Constants.INTENT_EXTRA_REVERT_QNUMBER)?.let {\n                showDescriptionEditRevertDialog(it)\n            }\n        } else if (ACTION_LOAD_FROM_EXISTING_TAB == intent.action && intent.hasExtra(EXTRA_HISTORYENTRY)) {\n            val title = intent.parcelableExtra<PageTitle>(Constants.ARG_TITLE)\n            val historyEntry = intent.parcelableExtra<HistoryEntry>(EXTRA_HISTORYENTRY)\n            loadPage(title, historyEntry, TabPosition.EXISTING_TAB)\n        } else if (ACTION_RESUME_READING == intent.action || intent.hasExtra(Constants.INTENT_APP_SHORTCUT_CONTINUE_READING)) {\n            loadFilePageFromBackStackIfNeeded()\n        } else if (Intent.ACTION_SEARCH == intent.action) {\n            val query = intent.getStringExtra(SearchManager.QUERY)\n            val title = PageTitle(query, app.wikiSite)\n            val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_SEARCH)\n            loadPage(title, historyEntry, TabPosition.EXISTING_TAB)\n        } else if (ACTION_CREATE_NEW_TAB == intent.action) {\n            loadMainPage(TabPosition.NEW_TAB_FOREGROUND)\n        } else {\n            loadMainPage(TabPosition.CURRENT_TAB)\n        }\n    }\n\n    /**\n     * Load a new page, and put it on top of the backstack, optionally allowing state loss of the\n     * fragment manager. Useful for when this function is called from an AsyncTask result.\n     * @param pageTitle Title of the page to load.\n     * @param entry HistoryEntry associated with this page.\n     * @param position Whether to open this page in the current tab, a new background tab, or new\n     * foreground tab.\n     * @param highlightText Text to highlight and scroll to once the page loads, only for the current tab.\n     */\n    private fun loadPage(pageTitle: PageTitle?, entry: HistoryEntry?, position: TabPosition, highlightText: String? = null) {\n        if (isDestroyed || pageTitle == null || entry == null) {\n            return\n        }\n        if (hasTransitionAnimation && !wasTransitionShown) {\n            binding.pageFragment.visibility = View.GONE\n            binding.wikiArticleCardView.prepareForTransition(pageTitle)\n            wasTransitionShown = true\n        }\n        if (loadNonArticlePageIfNeeded(pageTitle)) {\n            return\n        }\n\n        // Accessibility\n        title = getString(R.string.page_content_description, pageTitle.displayText)\n\n        binding.pageToolbarContainer.post {\n            if (!pageFragment.isAdded) {\n                return@post\n            }\n\n            // Close the link preview, if one is open.\n            hideLinkPreview()\n            onPageCloseActionMode()\n            when (position) {\n                TabPosition.CURRENT_TAB -> pageFragment.loadPage(pageTitle, entry, pushBackStack = true, squashBackstack = false, highlightText = highlightText)\n                TabPosition.CURRENT_TAB_SQUASH -> pageFragment.loadPage(pageTitle, entry, pushBackStack = true, squashBackstack = true, highlightText = highlightText)\n                TabPosition.NEW_TAB_BACKGROUND -> pageFragment.openInNewBackgroundTab(pageTitle, entry)\n                TabPosition.NEW_TAB_FOREGROUND -> pageFragment.openInNewForegroundTab(pageTitle, entry)\n                else -> pageFragment.openFromExistingTab(pageTitle, entry)\n            }\n            // Reusing an already-loaded page does not trigger onPageLoadComplete().\n            if (pageFragment.page != null && !pageFragment.isLoading) {\n                scheduleSemanticSearchFeedback()\n            }\n        }\n    }\n\n    private fun loadMainPage(position: TabPosition) {\n        val title = PageTitle(MainPageNameData.valueFor(app.appOrSystemLanguageCode), app.wikiSite)\n        val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_MAIN_PAGE)\n        loadPage(title, historyEntry, position)\n    }\n\n    private fun loadFilePageFromBackStackIfNeeded() {\n        if (pageFragment.currentTab.backStack.isNotEmpty()) {\n            val item = pageFragment.currentTab.backStack[pageFragment.currentTab.backStackPosition]\n            loadNonArticlePageIfNeeded(item.title)\n        }\n    }\n\n    private fun loadNonArticlePageIfNeeded(title: PageTitle?): Boolean {\n        if (title != null) {\n            if (title.isFilePage) {\n                startActivity(FilePageActivity.newIntent(this, title))\n                finish()\n                return true\n            } else if (title.namespace() === Namespace.USER_TALK || title.namespace() === Namespace.TALK) {\n                startActivity(TalkTopicsActivity.newIntent(this, title, InvokeSource.PAGE_ACTIVITY))\n                finish()\n                return true\n            } else if (title.isSpecial) {\n                if (title.isContributions) {\n                    title.displayText.split('/').lastOrNull()?.let {\n                        startActivity(UserContribListActivity.newIntent(this, it))\n                        finish()\n                        return true\n                    }\n                }\n                UriUtil.visitInExternalBrowser(this, title.uri.toUri())\n                finish()\n                return true\n            }\n        }\n        return false\n    }\n\n    private fun updateProgressBar(visible: Boolean) {\n        binding.pageProgressBar.visibility = if (visible) View.VISIBLE else View.GONE\n    }\n\n    private fun hideLinkPreview() {\n        ExclusiveBottomSheetPresenter.dismiss(supportFragmentManager)\n    }\n\n    private fun removeTransitionAnimState() {\n        if (binding.pageFragment.visibility != View.VISIBLE) {\n            binding.pageFragment.visibility = View.VISIBLE\n        }\n        if (binding.wikiArticleCardView.visibility != View.GONE) {\n            binding.wikiArticleCardView.postDelayed({ binding.wikiArticleCardView.visibility = View.GONE }, 250L)\n        }\n    }\n\n    private fun modifyMenu(mode: ActionMode) {\n        val menu = mode.menu\n\n        // Hide context items that are intended for showing in external apps.\n        menu.children.forEach {\n            if (it.title.toString().contains(getString(R.string.search_hint)) ||\n                (it.title.toString().contains(getString(R.string.menu_text_select_define)) && pageFragment.shareHandler.shouldEnableWiktionaryDialog())) {\n                it.isVisible = false\n            }\n        }\n        // Append our custom items to the context menu.\n        mode.menuInflater.inflate(R.menu.menu_text_select, menu)\n    }\n\n    private fun showDescriptionEditRevertDialog(qNumber: String) {\n        MaterialAlertDialogBuilder(this)\n            .setTitle(R.string.notification_reverted_title)\n            .setView(DescriptionEditRevertHelpView(this, qNumber))\n            .setPositiveButton(R.string.reverted_edit_dialog_ok_button_text, null)\n            .show()\n    }\n\n    private fun maybeShowThemeTooltip() {\n        if (!Prefs.showOneTimeCustomizeToolbarTooltip) {\n            return\n        }\n        enqueueTooltip {\n            FeedbackUtil.getTooltip(\n                this,\n                getString(R.string.theme_chooser_menu_item_short_tooltip),\n                arrowAnchorPadding = -DimenUtil.roundedDpToPx(7f),\n                topOrBottomMargin = 0,\n                aboveOrBelow = true,\n                autoDismiss = false,\n                showDismissButton = true\n            ).apply {\n                setOnBalloonDismissListener {\n                    Prefs.showOneTimeCustomizeToolbarTooltip = false\n                    isTooltipShowing = false\n                }\n                BreadCrumbLogEvent.logTooltipShown(this@PageActivity, binding.pageToolbarButtonShowOverflowMenu)\n                showAlignBottom(binding.pageToolbarButtonShowOverflowMenu)\n                setCurrentTooltip(this)\n                isTooltipShowing = true\n            }\n        }\n    }\n\n    private fun enqueueTooltip(runnable: Runnable) {\n        if (exclusiveTooltipRunnable != null) {\n            return\n        }\n        exclusiveTooltipRunnable = runnable\n        binding.pageToolbar.postDelayed({\n            exclusiveTooltipRunnable = null\n            if (isDestroyed) {\n                return@postDelayed\n            }\n            runnable.run()\n        }, 500)\n    }\n\n    fun animateTabsButton() {\n        toolbarHideHandler.ensureDisplayed()\n        binding.pageToolbarButtonTabs.updateTabCount(true)\n    }\n\n    private fun updateNotificationsButton(animate: Boolean) {\n        if (AccountUtil.isLoggedIn) {\n            binding.pageToolbarButtonNotifications.isVisible = true\n            if (Prefs.notificationUnreadCount > 0) {\n                binding.pageToolbarButtonNotifications.setUnreadCount(Prefs.notificationUnreadCount)\n                if (animate) {\n                    toolbarHideHandler.ensureDisplayed()\n                    binding.pageToolbarButtonNotifications.runAnimation()\n                }\n            } else {\n                binding.pageToolbarButtonNotifications.setUnreadCount(0)\n            }\n        } else if (!AccountUtil.isLoggedIn && AnonymousNotificationHelper.isWithinAnonNotificationTime()) {\n            binding.pageToolbarButtonNotifications.isVisible = true\n            if (Prefs.hasAnonymousNotification) {\n                binding.pageToolbarButtonNotifications.setUnreadCount(1)\n                if (animate) {\n                    toolbarHideHandler.ensureDisplayed()\n                    binding.pageToolbarButtonNotifications.runAnimation()\n                }\n            } else {\n                binding.pageToolbarButtonNotifications.setUnreadCount(0)\n            }\n        } else {\n            binding.pageToolbarButtonNotifications.isVisible = false\n        }\n    }\n\n    fun clearActionBarTitle() {\n        supportActionBar?.title = \"\"\n    }\n\n    fun getToolbarMargin(): Int {\n        return binding.pageToolbarContainer.height\n    }\n\n    fun getOverflowMenu(): View {\n        return binding.pageToolbarButtonShowOverflowMenu\n    }\n\n    override fun onUnreadNotification() {\n        updateNotificationsButton(true)\n    }\n\n    fun onAnonNotification() {\n        updateNotificationsButton(true)\n    }\n\n    fun updateSearchHint() {\n        binding.pageToolbarButtonSearch.text = getString(R.string.search_hint)\n    }\n\n    override fun onProvideAssistContent(outContent: AssistContent) {\n        super.onProvideAssistContent(outContent)\n        pageFragment.model.title?.let {\n            outContent.webUri = it.uri.toUri()\n        }\n    }\n\n    companion object {\n        private const val LANGUAGE_CODE_BUNDLE_KEY = \"language\"\n        private const val EXCEPTION_MESSAGE_WEBVIEW = \"webview\"\n        const val ACTION_LOAD_IN_NEW_TAB = \"org.wikipedia.load_in_new_tab\"\n        const val ACTION_LOAD_IN_CURRENT_TAB = \"org.wikipedia.load_in_current_tab\"\n        const val ACTION_LOAD_IN_CURRENT_TAB_SQUASH = \"org.wikipedia.load_in_current_tab_squash\"\n        const val ACTION_LOAD_FROM_EXISTING_TAB = \"org.wikipedia.load_from_existing_tab\"\n        const val ACTION_CREATE_NEW_TAB = \"org.wikipedia.create_new_tab\"\n        const val ACTION_RESUME_READING = \"org.wikipedia.resume_reading\"\n        const val EXTRA_HISTORYENTRY = \"org.wikipedia.history.historyentry\"\n        const val EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK = \"org.wikipedia.search.semantic.show_feedback\"\n        const val EXTRA_SEMANTIC_SEARCH_ID = \"org.wikipedia.search.semantic.search_id\"\n        const val EXTRA_SEMANTIC_SEARCH_FUNNEL = \"org.wikipedia.search.semantic.funnel\"\n        const val EXTRA_HIGHLIGHT_TEXT = \"org.wikipedia.page.highlight_text\"\n\n        fun newIntent(context: Context): Intent {\n            return Intent(ACTION_RESUME_READING).setClass(context, PageActivity::class.java)\n        }\n\n        fun newIntentForNewTab(context: Context): Intent {\n            return Intent(ACTION_CREATE_NEW_TAB).setClass(context, PageActivity::class.java)\n        }\n\n        fun newIntentForNewTab(context: Context, entry: HistoryEntry, title: PageTitle): Intent {\n            return Intent(ACTION_LOAD_IN_NEW_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n\n        fun newIntentForCurrentTab(context: Context, entry: HistoryEntry, title: PageTitle, squashBackstack: Boolean = true): Intent {\n            return Intent(if (squashBackstack) ACTION_LOAD_IN_CURRENT_TAB_SQUASH else ACTION_LOAD_IN_CURRENT_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n\n        fun newIntentForExistingTab(context: Context, entry: HistoryEntry, title: PageTitle): Intent {\n            return Intent(ACTION_LOAD_FROM_EXISTING_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageActivity.kt","kind":"class","line":112,"members":{"ACTION_CREATE_NEW_TAB":[1000,1000],"ACTION_LOAD_FROM_EXISTING_TAB":[999,999],"ACTION_LOAD_IN_CURRENT_TAB":[997,997],"ACTION_LOAD_IN_CURRENT_TAB_SQUASH":[998,998],"ACTION_LOAD_IN_NEW_TAB":[996,996],"ACTION_RESUME_READING":[1001,1001],"EXCEPTION_MESSAGE_WEBVIEW":[995,995],"EXTRA_HIGHLIGHT_TEXT":[1006,1006],"EXTRA_HISTORYENTRY":[1002,1002],"EXTRA_SEMANTIC_SEARCH_FUNNEL":[1005,1005],"EXTRA_SEMANTIC_SEARCH_ID":[1004,1004],"EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK":[1003,1003],"LANGUAGE_CODE_BUNDLE_KEY":[994,994],"TabPosition":[114,116],"animateTabsButton":[929,932],"app":[121,121],"binding":[118,118],"cancelSemanticSearchFeedback":[491,499],"clearActionBarTitle":[962,964],"currentActionModes":[124,124],"enqueueTooltip":[915,927],"exclusiveTooltipRunnable":[126,126],"getOverflowMenu":[970,972],"getToolbarMargin":[966,968],"handleIntent":[616,762],"hasTransitionAnimation":[122,122],"hideLinkPreview":[854,856],"isCabOpen":[125,125],"isTooltipShowing":[127,127],"loadFilePageFromBackStackIfNeeded":[817,822],"loadMainPage":[811,815],"loadNonArticlePageIfNeeded":[824,848],"loadPage":[764,809],"maybeShowThemeTooltip":[889,913],"modifyMenu":[867,879],"newIntent":[1008,1010],"newIntentForCurrentTab":[1023,1028],"newIntentForExistingTab":[1030,1035],"newIntentForNewTab":[1012,1014],"onActionModeFinished":[384,387],"onActionModeStarted":[374,382],"onAnonNotification":[978,980],"onBackPressedCallback":[410,432],"onCreate":[201,315],"onDestroy":[389,398],"onKeyDown":[434,440],"onLinkPreviewLoadPage":[612,614],"onNavMenuSwipeRequest":[442,447],"onNewIntent":[400,404],"onOptionsItemSelected":[342,353],"onPageCloseActionMode":[558,564],"onPageDismissBottomSheet":[508,510],"onPageHideSoftKeyboard":[536,538],"onPageInitWebView":[512,514],"onPageLoadComplete":[449,457],"onPageLoadError":[544,548],"onPageLoadErrorBackPressed":[550,552],"onPageLoadMainPageInForegroundTab":[524,526],"onPageLoadPage":[516,518],"onPageRequestAddImageTags":[608,610],"onPageRequestEditDescription":[603,606],"onPageRequestEditSection":[566,584],"onPageRequestGallery":[595,601],"onPageRequestLangLinks":[591,593],"onPageSetToolbarElevationEnabled":[554,556],"onPageShowLinkPreview":[520,522],"onPageStartSupportActionMode":[532,534],"onPageUpdateProgressBar":[528,530],"onPageWatchlistExpirySelect":[540,542],"onPause":[362,367],"onPrepareOptionsMenu":[335,340],"onProvideAssistContent":[986,991],"onResume":[355,360],"onSaveInstanceState":[369,372],"onStart":[317,333],"onUnreadNotification":[974,976],"openVisualEditorInExternalBrowser":[586,589],"pageFragment":[120,120],"removeTransitionAnimState":[858,865],"requestBrowseTabLauncher":[161,173],"requestEditSectionLauncher":[131,145],"requestGalleryEditLauncher":[155,159],"requestHandleIntentLauncher":[147,153],"requestSuggestedEditsLauncher":[175,199],"scheduleSemanticSearchFeedback":[459,489],"semanticSearchFeedbackJob":[129,129],"semanticSearchFeedbackViewModel":[128,128],"showDescriptionEditRevertDialog":[881,887],"submitSemanticSearchFeedbackSuppressed":[501,506],"toolbarHideHandler":[119,119],"updateForLoginState":[406,408],"updateNotificationsButton":[934,960],"updateProgressBar":[850,852],"updateSearchHint":[982,984],"wasTransitionShown":[123,123]},"shot":"shots/code/PageActivity.jpg","supers":["BaseActivity()","PageFragment.Callback","LinkPreviewDialog.LoadPageCallback","FrameLayoutNavMenuTriggerer.Callback"]},"PageFragment":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-widgets","Screen \u00b7 view composition"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class PageFragment : Fragment(), BackPressedHandler, CommunicationBridge.CommunicationBridgeListener, ThemeChooserDialog.Callback,\n    ReferenceDialog.Callback, WiktionaryDialog.Callback, WatchlistExpiryDialog.Callback {\n\n    interface Callback {\n        fun onPageDismissBottomSheet()\n        fun onPageLoadComplete()\n        fun onPageLoadPage(title: PageTitle, entry: HistoryEntry)\n        fun onPageInitWebView(v: ObservableWebView)\n        fun onPageShowLinkPreview(entry: HistoryEntry)\n        fun onPageLoadMainPageInForegroundTab()\n        fun onPageUpdateProgressBar(visible: Boolean)\n        fun onPageStartSupportActionMode(callback: ActionMode.Callback)\n        fun onPageHideSoftKeyboard()\n        fun onPageWatchlistExpirySelect(expiry: WatchlistExpiry)\n        fun onPageLoadError(title: PageTitle)\n        fun onPageLoadErrorBackPressed()\n        fun onPageSetToolbarElevationEnabled(enabled: Boolean)\n        fun onPageCloseActionMode()\n        fun onPageRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?)\n        fun onPageRequestLangLinks(title: PageTitle, historyEntryId: Long)\n        fun onPageRequestGallery(title: PageTitle, fileName: String, wikiSite: WikiSite, revision: Long, isLeadImage: Boolean, options: ActivityOptionsCompat?)\n        fun onPageRequestAddImageTags(mwQueryPage: MwQueryPage, invokeSource: InvokeSource)\n        fun onPageRequestEditDescription(text: String?, title: PageTitle, sourceSummary: PageSummaryForEdit?,\n                                         targetSummary: PageSummaryForEdit?, action: DescriptionEditActivity.Action, invokeSource: InvokeSource)\n    }\n\n    private var campaignDialog: CampaignDialog? = null\n    private val donationReminderLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode == DonationReminderActivity.RESULT_OK_FROM_DONATION_REMINDER) {\n            campaignDialog?.dismiss()\n        }\n    }\n\n    private var _binding: FragmentPageBinding? = null\n    val binding get() = _binding!!\n\n    private val activeTimer = ActiveTimer()\n    private val scrollTriggerListener = WebViewScrollTriggerListener()\n    private val pageRefreshListener = OnRefreshListener {\n        webView.clearCache(true)\n        refreshPage()\n    }\n    private val pageActionItemCallback = PageActionItemCallback()\n\n    private lateinit var bridge: CommunicationBridge\n    private lateinit var leadImagesHandler: LeadImagesHandler\n    private lateinit var pageFragmentLoadState: PageFragmentLoadState\n    private lateinit var bottomBarHideHandler: ViewHideHandler\n    internal var articleInteractionEvent: ArticleInteractionEvent? = null\n    private var pageRefreshed = false\n    private var errorState = false\n    private var scrolledUpForThemeChange = false\n    private var references: PageReferences? = null\n    private var avPlayer: AvPlayer? = null\n    private var avCallback: AvCallback? = null\n    private var sections: MutableList<Section>? = null\n    private var editCount = 0\n    private var app = WikipediaApp.instance\n\n    override lateinit var linkHandler: LinkHandler\n    override lateinit var webView: ObservableWebView\n    override var model = PageViewModel()\n    override val toolbarMargin get() = (requireActivity() as PageActivity).getToolbarMargin()\n    override val isPreview get() = false\n    override val referencesGroup get() = references?.referencesGroup\n    override val selectedReferenceIndex get() = references?.selectedIndex ?: 0\n    override var messageCardHeight: Float = 0f\n\n    lateinit var sidePanelHandler: SidePanelHandler\n    lateinit var shareHandler: ShareHandler\n    lateinit var editHandler: EditHandler\n    var revision = 0L\n\n    private val shouldCreateNewTab get() = currentTab.backStack.isNotEmpty()\n    private val backgroundTabPosition get() = 0.coerceAtLeast(foregroundTabPosition - 1)\n    private val foregroundTabPosition get() = app.tabList.size\n    private val tabLayoutOffsetParams get() = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, binding.pageActionsTabLayout.height)\n    val currentTab get() = app.tabList.last()\n    val title get() = model.title\n    val page get() = model.page\n    val isLoading get() = bridge.isLoading\n    val leadImageEditLang get() = leadImagesHandler.callToActionEditLang\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentPageBinding.inflate(inflater, container, false)\n        webView = binding.pageWebView\n        initWebViewListeners()\n        binding.pageRefreshContainer.scrollableChild = webView\n        binding.pageRefreshContainer.setOnRefreshListener(pageRefreshListener)\n        val swipeOffset = DimenUtil.getContentTopOffsetPx(requireActivity()) + REFRESH_SPINNER_ADDITIONAL_OFFSET\n        binding.pageRefreshContainer.setProgressViewOffset(false, -swipeOffset, swipeOffset)\n        binding.pageActionsTabLayout.callback = pageActionItemCallback\n        savedInstanceState?.let {\n            scrolledUpForThemeChange = it.getBoolean(ARG_THEME_CHANGE_SCROLLED, false)\n        }\n        return binding.root\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n        callback()?.onPageInitWebView(webView)\n        updateFontSize()\n\n        // Explicitly set background color of the WebView (independently of CSS, because\n        // the background may be shown momentarily while the WebView loads content,\n        // creating a seizure-inducing effect, or at the very least, a migraine with aura).\n        val activity = requireActivity()\n        webView.setBackgroundColor(ResourceUtil.getThemedColor(activity, R.attr.paper_color))\n        bridge = CommunicationBridge(this)\n        setupMessageHandlers()\n\n        binding.pageError.retryClickListener = View.OnClickListener { refreshPage() }\n        binding.pageError.backClickListener = View.OnClickListener {\n            if (!onBackPressed()) {\n                callback()?.onPageLoadErrorBackPressed()\n            }\n        }\n\n        bottomBarHideHandler = ViewHideHandler(binding.pageActionsTabContainer, null, Gravity.BOTTOM, updateElevation = false) { false }\n        bottomBarHideHandler.setScrollView(webView)\n        bottomBarHideHandler.enabled = Prefs.readingFocusModeEnabled\n\n        webView.addOnScrollChangeListener { _, scrollY, _ ->\n            if (scrollY > (DimenUtil.roundedDpToPx(webView.contentHeight.toFloat()) - (DimenUtil.displayHeightPx * 2)) &&\n                !model.isReadMoreLoaded) {\n                bridge.execute(JavaScriptActionHandler.appendReadMode(model))\n                model.isReadMoreLoaded = true\n            }\n        }\n\n        editHandler = EditHandler(this, bridge)\n        sidePanelHandler = SidePanelHandler(this, bridge)\n        leadImagesHandler = LeadImagesHandler(this, webView, binding.pageHeaderView, callback())\n        shareHandler = ShareHandler(this, bridge)\n        pageFragmentLoadState = PageFragmentLoadState(model, this, webView, bridge, leadImagesHandler, currentTab)\n\n        if (callback() != null) {\n            LongPressHandler(webView, HistoryEntry.SOURCE_INTERNAL_LINK, PageContainerLongPressHandler(this))\n        }\n\n        if (shouldLoadFromBackstack(activity) || savedInstanceState != null) {\n            reloadFromBackstack()\n        }\n    }\n\n    override fun onSaveInstanceState(outState: Bundle) {\n        super.onSaveInstanceState(outState)\n        outState.putBoolean(ARG_THEME_CHANGE_SCROLLED, scrolledUpForThemeChange)\n    }\n\n    override fun onDestroyView() {\n        avPlayer?.let {\n            it.deinit()\n            avPlayer = null\n        }\n        // uninitialize the bridge, so that no further JS events can have any effect.\n        bridge.cleanup()\n        sidePanelHandler.log()\n        leadImagesHandler.dispose()\n        webView.clearAllListeners()\n        (webView.parent as ViewGroup).removeView(webView)\n        Prefs.isSuggestedEditsHighestPriorityEnabled = false\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        bridge.execute(JavaScriptActionHandler.pauseAllMedia())\n        if (avPlayer?.isPlaying == true) {\n            avPlayer?.stop()\n            updateProgressBar(false)\n        }\n        activeTimer.pause()\n        addTimeSpentReading(activeTimer.elapsedSec)\n        pageFragmentLoadState.updateCurrentBackStackItem()\n        app.commitTabState()\n        val time = if (app.tabList.size >= 1 && !pageFragmentLoadState.backStackEmpty()) System.currentTimeMillis() else 0\n        Prefs.pageLastShown = time\n        articleInteractionEvent?.pause()\n    }\n\n    override fun onResume() {\n        super.onResume()\n        activeTimer.resume()\n        val params = CoordinatorLayout.LayoutParams(1, 1)\n        binding.pageImageTransitionHolder.layoutParams = params\n        binding.pageImageTransitionHolder.visibility = View.GONE\n        binding.pageActionsTabLayout.update()\n        updateQuickActionsAndMenuOptions()\n        if (ImageUrlUtil.isGif(page?.leadImageUrl)) {\n            leadImagesHandler.loadLeadImage()\n        }\n        articleInteractionEvent?.resume()\n        DonationReminderHelper.maybeShowSettingSnackbar(requireActivity())\n    }\n\n    override fun onConfigurationChanged(newConfig: Configuration) {\n        super.onConfigurationChanged(newConfig)\n        // if the screen orientation changes, then re-layout the lead image container,\n        // but only if we've finished fetching the page.\n        if (!bridge.isLoading && !errorState) {\n            pageFragmentLoadState.onConfigurationChanged()\n        }\n    }\n\n    override fun onBackPressed(): Boolean {\n        articleInteractionEvent?.logBackClick()\n        if (sidePanelHandler.isVisible) {\n            sidePanelHandler.hide()\n            return true\n        }\n        if (pageFragmentLoadState.goBack()) {\n            return true\n        }\n        // if the current tab can no longer go back, then close the tab before exiting\n        if (app.tabList.isNotEmpty()) {\n            app.tabList.removeAt(app.tabList.size - 1)\n            app.commitTabState()\n        }\n        return false\n    }\n\n    override fun onToggleDimImages() {\n        ActivityCompat.recreate(requireActivity())\n    }\n\n    override fun onToggleReadingFocusMode() {\n        webView.scrollEventsEnabled = false\n        bottomBarHideHandler.enabled = Prefs.readingFocusModeEnabled\n        leadImagesHandler.refreshCallToActionVisibility()\n        page?.let {\n            bridge.execute(JavaScriptActionHandler.setUpEditButtons(!Prefs.readingFocusModeEnabled, !it.canEdit))\n        }\n        // We disable and then re-enable scroll events coming from the WebView, because toggling\n        // reading focus mode within the article could actually change the dimensions of the page,\n        // which will cause extraneous scroll events to be sent.\n        binding.root.postDelayed({\n            if (isAdded) {\n                webView.scrollEventsEnabled = true\n            }\n        }, 250)\n    }\n\n    override fun onCancelThemeChooser() {\n        if (scrolledUpForThemeChange) {\n            val animDuration = 250L\n            ObjectAnimator.ofInt(webView, \"scrollY\", webView.scrollY, 0)\n                .setDuration(animDuration)\n                .start()\n        }\n    }\n\n    override fun onEditingPrefsChanged() { }\n\n    override fun wiktionaryShowDialogForTerm(term: String) {\n        shareHandler.showWiktionaryDefinition(term)\n    }\n\n    override fun onExpiryChanged(expiry: WatchlistExpiry) {\n        callback()?.onPageWatchlistExpirySelect(expiry)\n        dismissBottomSheet()\n    }\n\n    private fun shouldLoadFromBackstack(activity: Activity): Boolean {\n        return (activity.intent != null && (PageActivity.ACTION_RESUME_READING == activity.intent.action ||\n                activity.intent.hasExtra(Constants.INTENT_APP_SHORTCUT_CONTINUE_READING)))\n    }\n\n    private fun initWebViewListeners() {\n        webView.addOnUpOrCancelMotionEventListener {\n            // update our session, since it's possible for the user to remain on the page for\n            // a long time, and we wouldn't want the session to time out.\n            app.appSessionEvent.touchSession()\n        }\n        webView.addOnContentHeightChangedListener(scrollTriggerListener)\n        webView.webViewClient = object : OkHttpWebViewClient() {\n\n            override val model get() = this@PageFragment.model\n\n            override val linkHandler get() = this@PageFragment.linkHandler\n\n            override fun onPageFinished(view: WebView, url: String) {\n                bridge.evaluateImmediate(\"(function() { return (typeof pcs !== 'undefined'); })();\") { pcsExists ->\n                    if (!isAdded) {\n                        return@evaluateImmediate\n                    }\n                    // TODO: This is a bit of a hack: If PCS does not exist in the current page, then\n                    // it's implied that this page was loaded via Mobile Web (e.g. the Main Page) and\n                    // doesn't support PCS, meaning that we will never receive the `setup` event that\n                    // tells us the page is finished loading. In such a case, we must infer that the\n                    // page has now loaded and trigger the remaining logic ourselves.\n                    if (\"true\" != pcsExists) {\n                        if (WikipediaApp.instance.currentTheme.isDark) {\n                            // TODO: remove when mobile web supports automatic dark mode through\n                            // the `prefers-color-scheme` media query.\n                            bridge.execute(JavaScriptActionHandler.mobileWebSetDarkMode())\n                        }\n                        onPageSetupEvent()\n                        bridge.onMetadataReady()\n                        bridge.onPcsReady()\n                        bridge.execute(JavaScriptActionHandler.mobileWebChromeShim(DimenUtil.roundedPxToDp(((requireActivity() as AppCompatActivity).supportActionBar?.height ?: 0).toFloat()),\n                            DimenUtil.roundedPxToDp(binding.pageActionsTabLayout.height.toFloat())))\n\n                        // In the case of certain types of namespaces, especially pages with a lot of interactivity\n                        // that we can't control, we need to bounce them out explicitly to an external\n                        // browser, even after the page is fully loaded into our WebView. This is because\n                        // we can determine the namespace only after the loading sequence is in progress.\n                        if (model.page?.summary?.ns == Namespace.EVENT) {\n                            model.title?.let {\n                                UriUtil.visitInExternalBrowser(requireActivity(), it.uri.toUri())\n                                binding.root.post {\n                                    if (isAdded) {\n                                        requireActivity().onBackPressedDispatcher.onBackPressed()\n                                    }\n                                }\n                            }\n                        }\n                        callback()?.onPageLoadComplete()\n                    }\n                }\n            }\n\n            override fun onReceivedHttpError(view: WebView, request: WebResourceRequest, errorResponse: WebResourceResponse) {\n                if (!request.url.toString().contains(RestService.PAGE_HTML_ENDPOINT)) {\n                    // If the request is anything except the main mobile-html content request, then\n                    // don't worry about any errors and let the WebView deal with it.\n                    return\n                }\n                onPageLoadError(HttpStatusException(errorResponse.statusCode, request.url.toString(), UriUtil.decodeURL(errorResponse.reasonPhrase)))\n            }\n        }\n    }\n\n    private fun onPageSetupEvent() {\n        if (!isAdded) {\n            return\n        }\n        updateProgressBar(false)\n        webView.visibility = View.VISIBLE\n        bridge.evaluate(JavaScriptActionHandler.getRevision()) { value ->\n            if (!isAdded || value == null || value == \"null\") {\n                return@evaluate\n            }\n            try {\n                revision = value.replace(\"\\\"\", \"\").toLong()\n            } catch (e: Exception) {\n                L.e(e)\n            }\n        }\n        bridge.evaluate(JavaScriptActionHandler.getSections()) { value ->\n            if (!isAdded) {\n                return@evaluate\n            }\n            model.page?.let { page ->\n                sections = JsonUtil.decodeFromString(value)\n                sections?.let { sections ->\n                    sections.add(0, Section(0, 0, model.title?.displayText.orEmpty(), model.title?.displayText.orEmpty(), \"\"))\n                    page.sections = sections\n                }\n\n                sidePanelHandler.setupForNewPage(page)\n                sidePanelHandler.setEnabled(true)\n                model.isReadMoreLoaded = false\n            }\n        }\n        bridge.evaluate(JavaScriptActionHandler.getProtection()) { value ->\n            if (!isAdded) {\n                return@evaluate\n            }\n            model.page?.let { page ->\n                page.protection = JsonUtil.decodeFromString(value)\n                updateQuickActionsAndMenuOptions()\n            }\n        }\n    }\n\n    private fun handleInternalLink(title: PageTitle) {\n        if (!isResumed) {\n            return\n        }\n        if (title.namespace() === Namespace.USER_TALK || title.namespace() === Namespace.TALK) {\n            startTalkTopicsActivity(title)\n            return\n        } else if (title.namespace() == Namespace.CATEGORY) {\n            startActivity(CategoryActivity.newIntent(requireActivity(), title))\n            return\n        }\n\n        dismissBottomSheet()\n        val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_INTERNAL_LINK).apply {\n            prevId = model.curEntry?.id ?: -1\n        }\n\n        if (title == model.title && !title.fragment.isNullOrEmpty()) {\n            scrollToSection(title.fragment!!)\n            return\n        }\n\n        model.title?.run {\n            historyEntry.referrer = uri\n        }\n        if (title.namespace() !== Namespace.MAIN || !Prefs.isLinkPreviewEnabled) {\n            loadPage(title, historyEntry)\n        } else {\n            callback()?.onPageShowLinkPreview(historyEntry)\n        }\n    }\n\n    private fun setCurrentTabAndReset(position: Int) {\n        // move the selected tab to the bottom of the list, and navigate to it!\n        // (but only if it's a different tab than the one currently in view!\n        if (position < app.tabList.size - 1) {\n            val tab = app.tabList.removeAt(position)\n            app.tabList.add(tab)\n            pageFragmentLoadState.setTab(tab)\n        }\n        if (app.tabCount > 0) {\n            app.tabList.last().squashBackstack()\n            pageFragmentLoadState.loadFromBackStack()\n        }\n    }\n\n    private fun selectedTabPosition(title: PageTitle): Int {\n        return app.tabList.firstOrNull { it.backStackPositionTitle != null &&\n                title == it.backStackPositionTitle }?.let { app.tabList.indexOf(it) } ?: -1\n    }\n\n    private fun openInNewTab(title: PageTitle, entry: HistoryEntry, position: Int) {\n        val selectedTabPosition = selectedTabPosition(title)\n        if (selectedTabPosition >= 0) {\n            setCurrentTabAndReset(selectedTabPosition)\n            return\n        }\n        if (shouldCreateNewTab) {\n            // create a new tab\n            val tab = Tab()\n            val isForeground = position == foregroundTabPosition\n            // if the requested position is at the top, then make its backstack current\n            if (isForeground) {\n                pageFragmentLoadState.setTab(tab)\n            }\n            // put this tab in the requested position\n            app.tabList.add(position, tab)\n            trimTabCount()\n            // add the requested page to its backstack\n            tab.backStack.add(PageBackStackItem(title, entry))\n            if (!isForeground) {\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                    ServiceFactory.get(title.wikiSite).getInfoByPageIdsOrTitles(null, title.prefixedText)\n                        .query?.firstPage()?.let { page ->\n                            WikipediaApp.instance.tabList.find { it.backStackPositionTitle == title }?.backStackPositionTitle?.apply {\n                                thumbUrl = page.thumbUrl()\n                                description = page.description\n                            }\n                        }\n                }\n            }\n            requireActivity().invalidateOptionsMenu()\n        } else {\n            pageFragmentLoadState.setTab(currentTab)\n            currentTab.backStack.add(PageBackStackItem(title, entry))\n        }\n    }\n\n    private fun dismissBottomSheet() {\n        ExclusiveBottomSheetPresenter.dismiss(childFragmentManager)\n        callback()?.onPageDismissBottomSheet()\n    }\n\n    private fun updateProgressBar(visible: Boolean) {\n        callback()?.onPageUpdateProgressBar(visible)\n    }\n\n    private fun startLangLinksActivity() {\n        val historyEntryId = model.curEntry?.id ?: -1\n        model.title?.let {\n            callback()?.onPageRequestLangLinks(it, historyEntryId)\n        }\n    }\n\n    private fun trimTabCount() {\n        while (app.tabList.size > Constants.MAX_TABS) {\n            app.tabList.removeAt(0)\n        }\n    }\n\n    private fun addTimeSpentReading(timeSpentSec: Int) {\n        model.curEntry?.let {\n            MainScope().launch(CoroutineExceptionHandler { _, throwable -> L.e(throwable) }) {\n                AppDatabase.instance.pageImagesDao().upsertForTimeSpent(it, timeSpentSec)\n            }\n\n            // Update the article visit for Donation Reminder\n            DonationReminderHelper.increaseArticleVisitCount(timeSpentSec)\n        }\n    }\n\n    private fun getContentTopOffsetParams(context: Context): LinearLayout.LayoutParams {\n        return LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, DimenUtil.getContentTopOffsetPx(context))\n    }\n\n    private fun disableActionTabs(caught: Throwable?) {\n        val offline = ThrowableUtil.isOffline(caught)\n        for (i in 0 until binding.pageActionsTabLayout.childCount) {\n            if (!offline) {\n                binding.pageActionsTabLayout.disableTab(i)\n            }\n        }\n    }\n\n    private fun startTalkTopicsActivity(title: PageTitle, stripUrlFragment: Boolean = false) {\n        val talkTitle = title.copy()\n        if (stripUrlFragment) {\n            talkTitle.fragment = null\n        }\n        startActivity(TalkTopicsActivity.newIntent(requireActivity(), talkTitle, InvokeSource.PAGE_ACTIVITY))\n    }\n\n    private fun startGalleryActivity(fileName: String) {\n        if (app.isOnline) {\n            bridge.evaluate(JavaScriptActionHandler.getElementAtPosition(DimenUtil.roundedPxToDp(webView.lastTouchX),\n                DimenUtil.roundedPxToDp(webView.lastTouchY))) { s ->\n                if (!isAdded) {\n                    return@evaluate\n                }\n                var options: ActivityOptionsCompat? = null\n\n                val hitInfo: JavaScriptActionHandler.ImageHitInfo? = JsonUtil.decodeFromString(s)\n                hitInfo?.let {\n                    val params = CoordinatorLayout.LayoutParams(\n                        DimenUtil.roundedDpToPx(it.width),\n                        DimenUtil.roundedDpToPx(it.height)\n                    )\n                    params.topMargin = DimenUtil.roundedDpToPx(it.top)\n                    params.leftMargin = DimenUtil.roundedDpToPx(it.left)\n                    binding.pageImageTransitionHolder.layoutParams = params\n                    binding.pageImageTransitionHolder.visibility = View.VISIBLE\n                    ViewUtil.loadImage(binding.pageImageTransitionHolder, it.src)\n                    GalleryActivity.setTransitionInfo(it)\n                    options = ActivityOptionsCompat.makeSceneTransitionAnimation(requireActivity(),\n                        binding.pageImageTransitionHolder, getString(R.string.transition_page_gallery))\n                }\n                webView.post {\n                    if (!isAdded) {\n                        return@post\n                    }\n                    model.title?.let {\n                        callback()?.onPageRequestGallery(it, fileName, it.wikiSite, revision, false, options)\n                    }\n                }\n            }\n        } else {\n            val snackbar = FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.gallery_not_available_offline_snackbar))\n            snackbar.setAction(R.string.gallery_not_available_offline_snackbar_dismiss) { snackbar.dismiss() }\n            snackbar.show()\n        }\n    }\n\n    private fun hidePageContent() {\n        leadImagesHandler.hide()\n        bridge.loadBlankPage()\n        webView.visibility = View.INVISIBLE\n    }\n\n    fun updateWatchlistExpiry(expiry: WatchlistExpiry) {\n        model.hasWatchlistExpiry = expiry !== WatchlistExpiry.NEVER\n    }\n\n    private fun maybeShowAnnouncement() {\n        if (!lifecycle.currentState.isAtLeast(Lifecycle.State.RESUMED)) {\n            return\n        }\n        title?.let { pageTitle ->\n            // Check if the pause time is older than 1 day.\n            val dateDiff = Duration.between(Instant.ofEpochMilli(Prefs.announcementPauseTime), Instant.now())\n            if (Prefs.hasVisitedArticlePage && dateDiff.toDays() >= 1) {\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                    val campaignList = CampaignCollection.getActiveCampaigns()\n                    val availableCampaign = campaignList.find { campaign -> campaign.getAssetsForLang(app.appOrSystemLanguageCode) != null }\n                    availableCampaign?.let {\n                        val campaignId = it.getIdForLang(app.appOrSystemLanguageCode)\n                        if (!Prefs.announcementShownDialogs.contains(campaignId)) {\n                            DonorExperienceEvent.logAction(\"impression\", \"article_banner\", pageTitle.wikiSite.languageCode, campaignId)\n                            campaignDialog = CampaignDialog(requireActivity(), it, onNeutralButtonClick = {\n                                donationReminderLauncher.launch(DonationReminderActivity.newIntent(requireContext()))\n                            })\n                            campaignDialog?.setCancelable(false)\n                            campaignDialog?.show()\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    private fun showFindReferenceInPage(referenceAnchor: String,\n                                        backLinksList: List<String?>,\n                                        referenceText: String) {\n        model.page?.run {\n            startSupportActionMode(object : ActionMode.Callback {\n                override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n                    val menuItem = menu.add(R.string.menu_page_find_in_page)\n                    menuItem.actionProvider = FindReferenceInPageActionProvider(requireContext(), referenceAnchor, referenceText, backLinksList)\n                    menuItem.expandActionView()\n                    return true\n                }\n\n                override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n                    mode.tag = \"actionModeFindReferenceInPage\"\n                    return false\n                }\n\n                override fun onActionItemClicked(mode: ActionMode, item: MenuItem): Boolean {\n                    return false\n                }\n\n                override fun onDestroyActionMode(mode: ActionMode) {\n                    bridge.execute(JavaScriptActionHandler.removeHighlights())\n                }\n            })\n        }\n    }\n\n    private fun setupMessageHandlers() {\n        linkHandler = object : LinkHandler(requireActivity()) {\n            override fun onPageLinkClicked(anchor: String, linkText: String) {\n                dismissBottomSheet()\n                bridge.execute(JavaScriptActionHandler.prepareToScrollTo(anchor, true))\n            }\n\n            override fun onInternalLinkClicked(title: PageTitle) {\n                handleInternalLink(title)\n            }\n\n            override fun onMediaLinkClicked(title: PageTitle) {\n                startGalleryActivity(title.prefixedText)\n            }\n\n            override fun onDiffLinkClicked(title: PageTitle, revisionId: Long) {\n                startActivity(ArticleEditDetailsActivity.newIntent(requireContext(), title, revisionId))\n            }\n\n            // ignore\n            override var wikiSite: WikiSite\n                get() = model.title?.run { wikiSite } ?: WikiSite.forLanguageCode(\"en\")\n                set(wikiSite) {\n                    // ignore\n                }\n        }\n        bridge.addListener(\"link\", linkHandler)\n        bridge.addListener(\"setup\") { _, _ -> onPageSetupEvent() }\n        bridge.addListener(\"final_setup\") { _, payload ->\n            if (!isAdded) {\n                return@addListener\n            }\n            bridge.onPcsReady()\n            articleInteractionEvent?.logLoaded()\n            callback()?.onPageLoadComplete()\n\n            JsonUtil.decodeFromElement<PageMetadata>(payload)?.let { metadata ->\n                // Persist the list of topics for this article.\n                // TODO: do something with the other bits of metadata?\n                model.curEntry?.let { entry ->\n                    if (metadata.topics.isNotEmpty()) {\n                        MainScope().launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                            AppDatabase.instance.pageTopicDao()\n                                .upsertForPage(entry, PageTopic.fromMetadata(entry, metadata.topics))\n                        }\n                    }\n                }\n            }\n\n            // do we have a URL fragment or highlight text to scroll to?\n            model.title?.let { prevTitle ->\n                if ((!prevTitle.fragment.isNullOrEmpty() || !model.pendingHighlightText.isNullOrEmpty()) && scrollTriggerListener.stagedScrollY == 0) {\n                    val scrollDelay = 100\n                    webView.postDelayed({\n                        if (!isAdded) {\n                            return@postDelayed\n                        }\n                        model.title?.let {\n                            jumpToHighlightOrSection(it.fragment, model.pendingHighlightText)\n                            model.pendingHighlightText = null\n                        }\n                    }, scrollDelay.toLong())\n                }\n            }\n        }\n        bridge.addListener(\"reference\") { _, messagePayload ->\n            if (!isAdded) {\n                return@addListener\n            }\n            references = JsonUtil.decodeFromElement<PageReferences>(messagePayload)\n            references?.let {\n                if (it.referencesGroup.isNotEmpty()) {\n                    showBottomSheet(ReferenceDialog())\n                }\n            }\n        }\n        bridge.addListener(\"back_link\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                val backLinks = payload[\"backLinks\"]?.jsonArray\n                if (!backLinks.isNullOrEmpty()) {\n                    val backLinksList = backLinks.map { it.jsonObject[\"id\"]?.jsonPrimitive?.content }\n                    showFindReferenceInPage(payload[\"referenceId\"]?.jsonPrimitive?.content.orEmpty(), backLinksList, payload[\"referenceText\"]?.jsonPrimitive?.content.orEmpty())\n                }\n            }\n        }\n        bridge.addListener(\"scroll_to_anchor\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                payload[\"rect\"]?.jsonObject?.let {\n                    val diffY = if (it.containsKey(\"y\")) DimenUtil.roundedDpToPx(it[\"y\"]!!.jsonPrimitive.float) else DimenUtil.roundedDpToPx(it[\"top\"]!!.jsonPrimitive.float)\n                    val offsetFraction = 3\n                    webView.scrollY = webView.scrollY + diffY - webView.height / offsetFraction\n                }\n            }\n        }\n        bridge.addListener(\"image\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                linkHandler.onUrlClick(UriUtil.decodeURL(payload[\"href\"]?.jsonPrimitive?.content.orEmpty()), payload[\"title\"]?.jsonPrimitive?.content, \"\")\n            }\n        }\n        bridge.addListener(\"media\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                linkHandler.onUrlClick(UriUtil.decodeURL(payload[\"href\"]?.jsonPrimitive?.content.orEmpty()), payload[\"title\"]?.jsonPrimitive?.content, \"\")\n            }\n        }\n        bridge.addListener(\"pronunciation\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                if (avPlayer == null) {\n                    avPlayer = AvPlayer()\n                }\n                if (avCallback == null) {\n                    avCallback = AvCallback()\n                }\n                if (!avPlayer!!.isPlaying && payload.containsKey(\"url\")) {\n                    updateProgressBar(true)\n                    avPlayer!!.play(UriUtil.resolveProtocolRelativeUrl(payload[\"url\"]?.jsonPrimitive?.content.orEmpty()), avCallback!!)\n                } else {\n                    updateProgressBar(false)\n                    avPlayer!!.stop()\n                }\n            }\n        }\n        bridge.addListener(\"footer_item\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                when (payload[\"itemType\"]?.jsonPrimitive?.content) {\n                    \"talkPage\" -> model.title?.run {\n                        articleInteractionEvent?.logTalkPageArticleClick()\n                        startTalkTopicsActivity(this, true)\n                    }\n                    \"languages\" -> startLangLinksActivity()\n                    \"lastEdited\" -> {\n                        model.title?.run {\n                            articleInteractionEvent?.logEditHistoryArticleClick()\n                            startActivity(EditHistoryListActivity.newIntent(requireContext(), this))\n                        }\n                    }\n                    \"coordinate\" -> {\n                        model.page?.let { page ->\n                            val location = page.summary.coordinates\n                            if (location != null) {\n                                PlacesEvent.logAction(\"places_click\", \"article_footer\")\n                                requireActivity().startActivity(PlacesActivity.newIntent(requireContext(), page.title, location))\n                            } else {\n                                FeedbackUtil.showMessage(this@PageFragment, getString(R.string.action_item_view_on_map_unavailable))\n                            }\n                        }\n                    }\n                    \"pageIssues\" -> {\n                        val array = payload[\"payload\"]\n                        if (array != null && array.jsonArray.isNotEmpty() && model.title != null) {\n                            val issues = array.jsonArray.mapNotNull {\n                                it.jsonObject[\"html\"]?.jsonPrimitive?.content\n                            }\n                            PageIssuesDialog(requireActivity(), model.title!!.wikiSite, issues) { url, title, linkText ->\n                                linkHandler.onUrlClick(url, title, linkText)\n                            }\n                                .setTitle(R.string.page_issues_title)\n                                .setPositiveButton(android.R.string.ok, null)\n                                .show()\n                        }\n                    }\n                    \"disambiguation\" -> {\n                        // TODO\n                        // messagePayload contains an array of URLs called \"payload\".\n                    }\n                }\n            }\n        }\n        bridge.addListener(\"read_more_titles_retrieved\") { _, _ -> }\n        bridge.addListener(\"view_license\") { _, _ ->\n            UriUtil.visitInExternalBrowser(requireContext(), Uri.parse(getString(R.string.cc_by_sa_4_url)))\n        }\n        bridge.addListener(\"view_in_browser\") { _, _ ->\n            model.title?.let {\n                UriUtil.visitInExternalBrowser(requireContext(), Uri.parse(it.uri))\n            }\n        }\n    }\n\n    fun reloadFromBackstack(forceReload: Boolean = true) {\n        if (pageFragmentLoadState.setTab(currentTab) || forceReload) {\n            if (!pageFragmentLoadState.backStackEmpty()) {\n                pageFragmentLoadState.loadFromBackStack()\n            } else {\n                callback()?.onPageLoadMainPageInForegroundTab()\n            }\n        }\n    }\n\n    fun onPageMetadataLoaded(redirectedFrom: String? = null, editCount: Int = -1) {\n        this.editCount = editCount\n        updateQuickActionsAndMenuOptions()\n        if (model.page == null) {\n            return\n        }\n        model.page?.run {\n            articleInteractionEvent = ArticleInteractionEvent(model.title?.wikiSite?.dbName()!!, summary.pageId)\n        }\n        editHandler.setPage(model.page)\n        binding.pageRefreshContainer.isEnabled = true\n        binding.pageRefreshContainer.isRefreshing = false\n        requireActivity().invalidateOptionsMenu()\n        redirectedFrom?.let {\n            FeedbackUtil.showMessage(requireActivity(), getString(R.string.redirected_from_snackbar, it), Snackbar.LENGTH_SHORT)\n        }\n        model.readingListPage?.let { page ->\n            model.title?.let { title ->\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t ->\n                    L.e(t)\n                }) {\n                    if (!page.thumbUrl.equals(title.thumbUrl, true) || !page.description.equals(title.description, true)) {\n                        AppDatabase.instance.readingListPageDao().updateThumbAndDescriptionByName(\n                            lang = page.wiki.languageCode,\n                            apiTitle = page.apiTitle,\n                            thumbUrl = title.thumbUrl,\n                            description = title.description\n                        )\n                    }\n                }\n            }\n        }\n        if (!errorState) {\n            editHandler.setPage(model.page)\n            webView.visibility = View.VISIBLE\n        }\n\n        maybeShowAnnouncement()\n\n        bridge.onMetadataReady()\n        // Explicitly set the top margin (even though it might have already been set in the setup\n        // handler), since the page metadata might have altered the lead image display state.\n        bridge.execute(JavaScriptActionHandler.setTopMargin(leadImagesHandler.topMargin))\n        bridge.execute(JavaScriptActionHandler.setFooter(model))\n    }\n\n    fun openInNewBackgroundTab(title: PageTitle, entry: HistoryEntry) {\n        if (app.tabCount == 0) {\n            openInNewTab(title, entry, foregroundTabPosition)\n            pageFragmentLoadState.loadFromBackStack()\n        } else {\n            openInNewTab(title, entry, backgroundTabPosition)\n            (requireActivity() as PageActivity).animateTabsButton()\n        }\n    }\n\n    fun openInNewForegroundTab(title: PageTitle, entry: HistoryEntry) {\n        openInNewTab(title, entry, foregroundTabPosition)\n        pageFragmentLoadState.loadFromBackStack()\n    }\n\n    fun openFromExistingTab(title: PageTitle, entry: HistoryEntry) {\n        val selectedTabPosition = selectedTabPosition(title)\n\n        if (selectedTabPosition == -1) {\n            loadPage(title, entry, pushBackStack = true, squashBackstack = false)\n            return\n        }\n        setCurrentTabAndReset(selectedTabPosition)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry, pushBackStack: Boolean, squashBackstack: Boolean, isRefresh: Boolean = false, highlightText: String? = null) {\n        // is the new title the same as what's already being displayed?\n        if (currentTab.backStack.isNotEmpty() &&\n                title == currentTab.backStack[currentTab.backStackPosition].title) {\n            if (model.page == null || isRefresh) {\n                if (highlightText.isNullOrEmpty()) {\n                    pageFragmentLoadState.loadFromBackStack()\n                } else {\n                    // Scroll to the highlighted passage instead of restoring the previous scroll position.\n                    loadPage(title, entry, false, 0, isRefresh, highlightText)\n                }\n            } else {\n                // Keep the model in sync so that a pending final_setup does not jump to a stale target.\n                model.title?.fragment = title.fragment\n                model.pendingHighlightText = highlightText\n                jumpToHighlightOrSection(title.fragment, highlightText)\n            }\n            return\n        }\n        if (squashBackstack) {\n            if (app.tabCount > 0) {\n                app.tabList.last().clearBackstack()\n            }\n        }\n        loadPage(title, entry, pushBackStack, 0, isRefresh, highlightText)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry, pushBackStack: Boolean, stagedScrollY: Int, isRefresh: Boolean = false, highlightText: String? = null) {\n        // clear the title in case the previous page load had failed.\n        clearActivityActionBarTitle()\n\n        if (ExclusiveBottomSheetPresenter.getCurrentBottomSheet(childFragmentManager) !is ThemeChooserDialog) {\n            dismissBottomSheet()\n        }\n\n        if (AccountUtil.isLoggedIn) {\n            // explicitly check notifications for the current user\n            PollNotificationWorker.schedulePollNotificationJob(requireContext())\n        }\n\n        EventPlatformClient.AssociationController.beginNewPageView()\n\n        // update the time spent reading of the current page, before loading the new one\n        addTimeSpentReading(activeTimer.elapsedSec)\n        activeTimer.reset()\n        callback()?.onPageSetToolbarElevationEnabled(false)\n        sidePanelHandler.setEnabled(false)\n        errorState = false\n        binding.pageError.visibility = View.GONE\n        model.title = title\n        model.pendingHighlightText = highlightText\n        model.curEntry = entry\n        model.page = null\n        model.readingListPage = null\n        model.forceNetwork = isRefresh\n        webView.visibility = View.VISIBLE\n        binding.pageActionsTabLayout.visibility = View.VISIBLE\n        binding.pageActionsTabLayout.enableAllTabs()\n        updateProgressBar(true)\n        pageRefreshed = isRefresh\n        references = null\n        revision = 0\n        pageFragmentLoadState.load(pushBackStack)\n        scrollTriggerListener.stagedScrollY = stagedScrollY\n    }\n\n    fun updateFontSize() {\n        webView.settings.defaultFontSize = app.getFontSize().toInt()\n    }\n\n    fun updateQuickActionsAndMenuOptions() {\n        if (!isAdded) {\n            return\n        }\n        binding.pageActionsTabLayout.forEach { it as MaterialTextView\n            val pageActionItem = PageActionItem.find(it.id)\n            var enabled = model.page != null && (!model.shouldLoadAsMobileWeb || (model.shouldLoadAsMobileWeb && pageActionItem.isAvailableOnMobileWeb))\n            when (pageActionItem) {\n                PageActionItem.ADD_TO_WATCHLIST -> {\n                    it.setText(if (model.isWatched) R.string.menu_page_unwatch else R.string.menu_page_watch)\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.watchlistIcon(model.isWatched, model.hasWatchlistExpiry), 0, 0)\n                    enabled = enabled && AccountUtil.isLoggedIn\n                }\n                PageActionItem.SAVE -> {\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.readingListIcon(model.isInReadingList), 0, 0)\n                }\n                PageActionItem.EDIT_ARTICLE -> {\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.editArticleIcon(model.page?.canEdit != true), 0, 0)\n                }\n                PageActionItem.VIEW_ON_MAP -> {\n                    val geoAvailable = model.page?.summary?.coordinates != null\n                    val tintColor = ResourceUtil.getThemedColorStateList(requireContext(), if (geoAvailable) R.attr.primary_color else R.attr.inactive_color)\n                    it.setTextColor(tintColor)\n                    TextViewCompat.setCompoundDrawableTintList(it, tintColor)\n                }\n                else -> { }\n            }\n            it.isEnabled = enabled\n            it.alpha = if (enabled) 1f else 0.5f\n        }\n        sidePanelHandler.setEnabled(false)\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    suspend fun updateBookmarkAndMenuOptionsFromDao() {\n        title?.let {\n            model.readingListPage = AppDatabase.instance.readingListPageDao().findPageInAnyList(it)\n            updateQuickActionsAndMenuOptions()\n            requireActivity().invalidateOptionsMenu()\n        }\n    }\n\n    fun onActionModeShown(mode: ActionMode) {\n        // make sure we have a page loaded, since shareHandler makes references to it.\n        model.page?.run {\n            shareHandler.onTextSelected(mode)\n        }\n    }\n\n    fun onRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?) {\n        callback()?.onPageRequestEditSection(sectionId, sectionAnchor, title, highlightText)\n    }\n\n    fun sharePageLink() {\n        model.title?.let {\n            ShareUtil.shareText(requireActivity(), it)\n        }\n    }\n\n    fun showFindInPage() {\n        model.title?.let { title ->\n            bridge.evaluate(JavaScriptActionHandler.expandCollapsedTables(true)) {\n                if (!isAdded) {\n                    return@evaluate\n                }\n                val articleFindInPageInteractionEvent = ArticleFindInPageInteractionEvent(model.page?.summary?.pageId ?: -1)\n                val findInPageActionProvider = FindInWebPageActionProvider(this, articleFindInPageInteractionEvent)\n                startSupportActionMode(object : ActionMode.Callback {\n                    override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n                        val menuItem = menu.add(R.string.menu_page_find_in_page)\n                        menuItem.actionProvider = findInPageActionProvider\n                        menuItem.expandActionView()\n                        callback()?.onPageSetToolbarElevationEnabled(false)\n                        return true\n                    }\n\n                    override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n                        mode.tag = \"actionModeFindInPage\"\n                        return false\n                    }\n\n                    override fun onActionItemClicked(mode: ActionMode, item: MenuItem): Boolean {\n                        return false\n                    }\n\n                    override fun onDestroyActionMode(mode: ActionMode) {\n                        if (!isAdded) {\n                            return\n                        }\n                        articleFindInPageInteractionEvent.pageHeight = webView.contentHeight\n                        articleFindInPageInteractionEvent.logDone()\n                        webView.clearMatches()\n                        callback()?.onPageHideSoftKeyboard()\n                        callback()?.onPageSetToolbarElevationEnabled(true)\n                    }\n                })\n            }\n        }\n    }\n\n    private fun scrollToSection(sectionAnchor: String) {\n        if (!isAdded) {\n            return\n        }\n        bridge.execute(JavaScriptActionHandler.clearHighlight())\n        bridge.execute(JavaScriptActionHandler.prepareToScrollTo(sectionAnchor, false))\n    }\n\n    private fun jumpToHighlightOrSection(sectionAnchor: String?, highlightText: String?) {\n        if (!highlightText.isNullOrEmpty()) {\n            bridge.evaluate(JavaScriptActionHandler.jumpToHighlightOrSection(sectionAnchor, highlightText)) { result ->\n                // ignore\n            }\n        } else if (!sectionAnchor.isNullOrEmpty()) {\n            scrollToSection(sectionAnchor)\n        }\n    }\n\n    fun onPageLoadError(caught: Throwable) {\n        if (!isAdded) {\n            return\n        }\n        title?.let {\n            updateProgressBar(false)\n            binding.pageRefreshContainer.isRefreshing = false\n            if (pageRefreshed) {\n                pageRefreshed = false\n            }\n            hidePageContent()\n            bridge.onMetadataReady()\n            if (binding.pageError.visibility != View.VISIBLE) {\n                binding.pageError.setError(caught, it)\n            }\n            binding.pageError.visibility = View.VISIBLE\n            binding.pageError.contentTopOffset.layoutParams = getContentTopOffsetParams(requireContext())\n            binding.pageError.contentTopOffset.visibility = View.VISIBLE\n            binding.pageError.tabLayoutOffset.layoutParams = tabLayoutOffsetParams\n            binding.pageError.tabLayoutOffset.visibility = View.VISIBLE\n            disableActionTabs(caught)\n            binding.pageRefreshContainer.isEnabled = !ThrowableUtil.is404(caught)\n            errorState = true\n            callback()?.onPageLoadError(it)\n        }\n    }\n\n    fun updateHeaderTopMargin() {\n        bridge.execute(JavaScriptActionHandler.setTopMargin(leadImagesHandler.topMargin))\n    }\n\n    fun updateMessageCardHeight() {\n        messageCardHeight = leadImagesHandler.getDonationReminderCardViewHeight()\n    }\n\n    fun refreshPage(stagedScrollY: Int = 0) {\n        if (bridge.isLoading) {\n            binding.pageRefreshContainer.isRefreshing = false\n            return\n        }\n        model.title?.let { title ->\n            model.curEntry?.let { entry ->\n                binding.pageError.visibility = View.GONE\n                binding.pageActionsTabLayout.enableAllTabs()\n                errorState = false\n                model.curEntry = HistoryEntry(title, HistoryEntry.SOURCE_HISTORY)\n                loadPage(title, entry, false, stagedScrollY, app.isOnline)\n            }\n        }\n    }\n\n   private fun clearActivityActionBarTitle() {\n        val currentActivity = requireActivity()\n        if (currentActivity is PageActivity) {\n            currentActivity.clearActionBarTitle()\n        }\n   }\n\n    fun verifyBeforeEditingDescription(text: String?, invokeSource: InvokeSource) {\n        page?.let {\n            if (!AccountUtil.isLoggedIn && Prefs.totalAnonDescriptionsEdited >= resources.getInteger(R.integer.description_max_anon_edits)) {\n                MaterialAlertDialogBuilder(requireActivity())\n                    .setMessage(R.string.description_edit_anon_limit)\n                    .setPositiveButton(R.string.page_editing_login) { _, _ ->\n                        startActivity(LoginActivity.newIntent(requireContext(), LoginActivity.SOURCE_EDIT))\n                    }\n                    .setNegativeButton(R.string.description_edit_login_cancel_button_text, null)\n                    .show()\n            } else {\n                startDescriptionEditActivity(text, invokeSource)\n            }\n        }\n    }\n\n    private fun startDescriptionEditActivity(text: String?, invokeSource: InvokeSource) {\n        title?.run {\n            val sourceSummary = PageSummaryForEdit(prefixedText, wikiSite.languageCode, this,\n                displayText, description, thumbUrl)\n            callback()?.onPageRequestEditDescription(text, this, sourceSummary, null,\n                DescriptionEditActivity.Action.ADD_DESCRIPTION, invokeSource)\n        }\n    }\n\n    fun goForward() {\n        pageFragmentLoadState.goForward()\n    }\n\n    fun showBottomSheet(dialog: BottomSheetDialogFragment) {\n        ExclusiveBottomSheetPresenter.show(childFragmentManager, dialog)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry) {\n        callback()?.onPageLoadPage(title, entry)\n    }\n\n    fun startSupportActionMode(actionModeCallback: ActionMode.Callback) {\n        callback()?.onPageStartSupportActionMode(actionModeCallback)\n    }\n\n    fun callback(): Callback? {\n        return getCallback(this, Callback::class.java)\n    }\n\n    fun updateWatchlist() {\n        title?.let {\n            lifecycleScope.launch(CoroutineExceptionHandler { _, throwable ->\n                FeedbackUtil.showError(requireActivity(), throwable)\n                L.d(throwable)\n            }) {\n                val pair = WatchlistViewModel.watchPageTitle(this, it, model.isWatched, WatchlistExpiry.NEVER, model.isWatched, it.namespace().talk())\n                model.isWatched = pair.first\n                updateWatchlistExpiry(WatchlistExpiry.NEVER)\n                WatchlistViewModel.showWatchlistSnackbar(requireActivity() as AppCompatActivity, childFragmentManager, it, pair.first, pair.second)\n                updateQuickActionsAndMenuOptions()\n            }\n        }\n    }\n\n    fun showAnonNotification() {\n        (requireActivity() as PageActivity).onAnonNotification()\n    }\n\n    fun showOverflowMenu(anchor: View) {\n        PageActionOverflowView(requireContext()).show(anchor, pageActionItemCallback, currentTab, model)\n    }\n\n    fun goToMainActivity(tab: NavTab, tabExtra: String) {\n        startActivity(MainActivity.newIntent(requireActivity())\n            .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)\n            .putExtra(Constants.INTENT_RETURN_TO_MAIN, true)\n            .putExtra(tabExtra, tab.code()))\n        requireActivity().finish()\n    }\n\n    fun dismissEditHandlerMenu(title: PageTitle?) {\n        title?.let {\n            EditAttemptStepEvent.logAbort(pageTitle = it, editCount = this.editCount)\n        }\n    }\n\n    private inner class AvCallback : AvPlayer.Callback {\n        override fun onSuccess() {\n            avPlayer?.stop()\n            updateProgressBar(false)\n        }\n\n        override fun onError(code: Int, extra: Int) {\n            if (avPlayer?.isPlaying == true) {\n                avPlayer?.stop()\n            }\n            FeedbackUtil.showMessage(this@PageFragment, R.string.media_playback_error)\n            updateProgressBar(false)\n        }\n    }\n\n    private inner class WebViewScrollTriggerListener : ObservableWebView.OnContentHeightChangedListener {\n        var stagedScrollY = 0\n        override fun onContentHeightChanged(contentHeight: Int) {\n            if (stagedScrollY > 0 && contentHeight * DimenUtil.densityScalar - webView.height > stagedScrollY) {\n                webView.scrollY = stagedScrollY\n                stagedScrollY = 0\n            }\n        }\n    }\n\n    private inner class FindReferenceInPageActionProvider constructor(context: Context,\n                                                                      private val referenceAnchor: String,\n                                                                      private val referenceText: String,\n                                                                      private val backLinksList: List<String?>) : ActionProvider(context), View.OnClickListener {\n        private val binding = GroupFindReferencesInPageBinding.inflate(LayoutInflater.from(context), null, false)\n        private var currentPos = 0\n\n        override fun onCreateActionView(): View {\n            binding.findInPagePrev.setOnClickListener(this)\n            binding.findInPageNext.setOnClickListener(this)\n            binding.referenceLabel.setOnClickListener(this)\n            binding.referenceLabel.text = getString(R.string.reference_list_title).plus(\" $referenceText\")\n            if (backLinksList.isNotEmpty()) {\n                scrollTo(0)\n            }\n            return binding.root\n        }\n\n        override fun overridesItemVisibility(): Boolean {\n            return true\n        }\n\n        override fun onClick(v: View) {\n            when (v) {\n                binding.findInPagePrev -> {\n                    if (backLinksList.isNotEmpty()) {\n                        currentPos = if (--currentPos < 0) backLinksList.size - 1 else currentPos\n                        scrollTo(currentPos)\n                    }\n                }\n                binding.findInPageNext -> {\n                    if (backLinksList.isNotEmpty()) {\n                        currentPos = if (++currentPos >= backLinksList.size) 0 else currentPos\n                        scrollTo(currentPos)\n                    }\n                }\n                binding.referenceLabel -> {\n                    bridge.execute(JavaScriptActionHandler.scrollToAnchor(referenceAnchor))\n                    callback()?.onPageCloseActionMode()\n                }\n            }\n        }\n\n        private fun scrollTo(position: Int) {\n            backLinksList[position]?.let {\n                binding.referenceCount.text = getString(R.string.find_in_page_result, position + 1,\n                    if (backLinksList.isEmpty()) 0 else backLinksList.size)\n                bridge.execute(JavaScriptActionHandler.prepareToScrollTo(it, true))\n            }\n        }\n    }\n\n    inner class PageActionItemCallback : PageActionItem.Callback {\n        override fun onSaveSelected() {\n            title?.let { SaveArticleSheetDialog.show(childFragmentManager, it) }\n            articleInteractionEvent?.logSaveClick()\n        }\n\n        override fun onLanguageSelected() {\n            startLangLinksActivity()\n            articleInteractionEvent?.logLanguageClick()\n        }\n\n        override fun onFindInArticleSelected() {\n            showFindInPage()\n            articleInteractionEvent?.logFindInArticleClick()\n        }\n\n        override fun onThemeSelected() {\n            articleInteractionEvent?.logThemeClick()\n\n            // If we're looking at the top of the article, then scroll down a bit so that at least\n            // some of the text is shown.\n            if (webView.scrollY < DimenUtil.leadImageHeightForDevice(requireActivity())) {\n                scrolledUpForThemeChange = true\n                val animDuration = 250\n                val anim = ObjectAnimator.ofInt(webView, \"scrollY\", webView.scrollY, DimenUtil.leadImageHeightForDevice(requireActivity()))\n                anim.setDuration(animDuration.toLong()).doOnEnd {\n                    showBottomSheet(ThemeChooserDialog.newInstance(InvokeSource.PAGE_ACTION_TAB))\n                }\n                anim.start()\n            } else {\n                scrolledUpForThemeChange = false\n                showBottomSheet(ThemeChooserDialog.newInstance(InvokeSource.PAGE_ACTION_TAB))\n            }\n        }\n\n        override fun onContentsSelected() {\n            sidePanelHandler.showToC()\n            articleInteractionEvent?.logContentsClick()\n        }\n\n        override fun onShareSelected() {\n            sharePageLink()\n            articleInteractionEvent?.logShareClick()\n        }\n\n        override fun onAddToWatchlistSelected() {\n            if (model.isWatched) {\n                WatchlistAnalyticsHelper.logRemovedFromWatchlist(model.title, requireContext())\n                articleInteractionEvent?.logUnWatchClick()\n            } else {\n                WatchlistAnalyticsHelper.logAddedToWatchlist(model.title, requireContext())\n                articleInteractionEvent?.logWatchClick()\n            }\n            updateWatchlist()\n        }\n\n        override fun onViewTalkPageSelected() {\n            title?.let {\n                startTalkTopicsActivity(it, true)\n            }\n            articleInteractionEvent?.logTalkPageClick()\n        }\n\n        override fun onViewEditHistorySelected() {\n            title?.run {\n                startActivity(EditHistoryListActivity.newIntent(requireContext(), this))\n            }\n            articleInteractionEvent?.logEditHistoryClick()\n        }\n\n        override fun onNewTabSelected() {\n            startActivity(PageActivity.newIntentForNewTab(requireContext()))\n            articleInteractionEvent?.logNewTabClick()\n        }\n\n        override fun onHomeSelected() {\n            goToMainActivity(tab = NavTab.HOME, tabExtra = Constants.INTENT_EXTRA_GO_TO_MAIN_TAB)\n            articleInteractionEvent?.logHomeClick()\n        }\n\n        override fun onCategoriesSelected() {\n            title?.let {\n                ExclusiveBottomSheetPresenter.show(childFragmentManager, CategoryDialog.newInstance(it))\n            }\n            articleInteractionEvent?.logCategoriesClick()\n        }\n\n        override fun onEditArticleSelected() {\n            editHandler.startEditingArticle()\n            articleInteractionEvent?.logEditArticleClick()\n        }\n\n        override fun onViewOnMapSelected() {\n            title?.let {\n                val location = page?.summary?.coordinates\n                if (location != null) {\n                    PlacesEvent.logAction(\"places_click\", \"article_more_menu\")\n                    requireActivity().startActivity(PlacesActivity.newIntent(requireContext(), it, location))\n                } else {\n                    FeedbackUtil.showMessage(this@PageFragment, getString(R.string.action_item_view_on_map_unavailable))\n                }\n            }\n        }\n\n        override fun forwardClick() {\n            goForward()\n            articleInteractionEvent?.logForwardClick()\n        }\n    }\n\n    companion object {\n        private const val ARG_THEME_CHANGE_SCROLLED = \"themeChangeScrolled\"\n        private val REFRESH_SPINNER_ADDITIONAL_OFFSET = (16 * DimenUtil.densityScalar).toInt()\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageFragment.kt","kind":"class","line":123,"members":{"ARG_THEME_CHANGE_SCROLLED":[1522,1522],"AvCallback":[1334,1347],"Callback":[126,147],"FindReferenceInPageActionProvider":[1359,1409],"PageActionItemCallback":[1411,1519],"REFRESH_SPINNER_ADDITIONAL_OFFSET":[1523,1523],"WebViewScrollTriggerListener":[1349,1357],"_binding":[156,156],"activeTimer":[159,159],"addTimeSpentReading":[610,619],"app":[180,180],"articleInteractionEvent":[171,171],"avCallback":[177,177],"avPlayer":[176,176],"backgroundTabPosition":[197,197],"binding":[157,157],"bottomBarHideHandler":[170,170],"bridge":[167,167],"callback":[1293,1295],"campaignDialog":[149,149],"clearActivityActionBarTitle":[1245,1250],"currentTab":[200,200],"disableActionTabs":[625,632],"dismissBottomSheet":[588,591],"dismissEditHandlerMenu":[1328,1332],"donationReminderLauncher":[150,154],"editCount":[179,179],"editHandler":[193,193],"errorState":[173,173],"foregroundTabPosition":[198,198],"getContentTopOffsetParams":[621,623],"goForward":[1277,1279],"goToMainActivity":[1320,1326],"handleInternalLink":[500,530],"hidePageContent":[682,686],"initWebViewListeners":[392,455],"isLoading":[203,203],"isPreview":[186,186],"jumpToHighlightOrSection":[1184,1192],"leadImageEditLang":[204,204],"leadImagesHandler":[168,168],"linkHandler":[182,182],"loadPage":[1006,1031],"maybeShowAnnouncement":[692,717],"messageCardHeight":[189,189],"model":[184,184],"onActionModeShown":[1118,1123],"onBackPressed":[329,344],"onCancelThemeChooser":[367,374],"onConfigurationChanged":[320,327],"onCreateView":[206,219],"onDestroyView":[273,287],"onEditingPrefsChanged":[376,376],"onExpiryChanged":[382,385],"onPageLoadError":[1194,1219],"onPageMetadataLoaded":[935,979],"onPageSetupEvent":[457,498],"onPause":[289,303],"onRequestEditSection":[1125,1127],"onResume":[305,318],"onSaveInstanceState":[268,271],"onToggleDimImages":[346,348],"onToggleReadingFocusMode":[350,365],"onViewCreated":[221,266],"openFromExistingTab":[996,1004],"openInNewBackgroundTab":[981,989],"openInNewForegroundTab":[991,994],"openInNewTab":[551,586],"page":[202,202],"pageActionItemCallback":[165,165],"pageFragmentLoadState":[169,169],"pageRefreshListener":[161,164],"pageRefreshed":[172,172],"references":[175,175],"referencesGroup":[187,187],"refreshPage":[1229,1243],"reloadFromBackstack":[925,933],"revision":[194,194],"scrollToSection":[1176,1182],"scrollTriggerListener":[160,160],"scrolledUpForThemeChange":[174,174],"sections":[178,178],"selectedReferenceIndex":[188,188],"selectedTabPosition":[546,549],"setCurrentTabAndReset":[532,544],"setupMessageHandlers":[747,923],"shareHandler":[192,192],"sharePageLink":[1129,1133],"shouldCreateNewTab":[196,196],"shouldLoadFromBackstack":[387,390],"showAnonNotification":[1312,1314],"showBottomSheet":[1281,1283],"showFindInPage":[1135,1174],"showFindReferenceInPage":[719,745],"showOverflowMenu":[1316,1318],"sidePanelHandler":[191,191],"startDescriptionEditActivity":[1268,1275],"startGalleryActivity":[642,680],"startLangLinksActivity":[597,602],"startSupportActionMode":[1289,1291],"startTalkTopicsActivity":[634,640],"tabLayoutOffsetParams":[199,199],"title":[201,201],"toolbarMargin":[185,185],"trimTabCount":[604,608],"updateBookmarkAndMenuOptionsFromDao":[1110,1116],"updateFontSize":[1072,1074],"updateHeaderTopMargin":[1221,1223],"updateMessageCardHeight":[1225,1227],"updateProgressBar":[593,595],"updateQuickActionsAndMenuOptions":[1076,1108],"updateWatchlist":[1297,1310],"updateWatchlistExpiry":[688,690],"verifyBeforeEditingDescription":[1252,1266],"webView":[183,183],"wiktionaryShowDialogForTerm":[378,380]},"shot":"shots/code/PageFragment.jpg","supers":["Fragment()","BackPressedHandler","CommunicationBridge.CommunicationBridgeListener","ThemeChooserDialog.Callback","ReferenceDialog.Callback","WiktionaryDialog.Callback","WatchlistExpiryDialog.Callback"]},"PageFragmentLoadState":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"]],"code":"class PageFragmentLoadState(private var model: PageViewModel,\n                            private var fragment: PageFragment,\n                            private var webView: ObservableWebView,\n                            private var bridge: CommunicationBridge,\n                            private var leadImagesHandler: LeadImagesHandler,\n                            private var currentTab: Tab) {\n    private var pageLoadJob: Job? = null\n\n    fun load(pushBackStack: Boolean) {\n        if (pushBackStack && model.title != null && model.curEntry != null) {\n            // update the topmost entry in the backstack, before we start overwriting things.\n            updateCurrentBackStackItem()\n            currentTab.pushBackStackItem(PageBackStackItem(model.title!!, model.curEntry!!))\n        }\n        pageLoad()\n    }\n\n    fun loadFromBackStack() {\n        if (currentTab.backStack.isEmpty()) {\n            return\n        }\n        val item = currentTab.backStack[currentTab.backStackPosition]\n        // display the page based on the backstack item, stage the scrollY position based on\n        // the backstack item.\n        fragment.loadPage(item.title, item.historyEntry, false, item.scrollY)\n        L.d(\"Loaded page \" + item.title.displayText + \" from backstack\")\n    }\n\n    fun updateCurrentBackStackItem() {\n        if (currentTab.backStack.isEmpty()) {\n            return\n        }\n        val item = currentTab.backStack[currentTab.backStackPosition]\n        item.scrollY = webView.scrollY\n        model.title?.let {\n            item.title.description = it.description\n            item.title.thumbUrl = it.thumbUrl\n        }\n    }\n\n    fun setTab(tab: Tab): Boolean {\n        val isDifferent = tab != currentTab\n        currentTab = tab\n        return isDifferent\n    }\n\n    fun goBack(): Boolean {\n        if (currentTab.canGoBack()) {\n            currentTab.moveBack()\n            if (!backStackEmpty()) {\n                loadFromBackStack()\n                return true\n            }\n        }\n        return false\n    }\n\n    fun goForward(): Boolean {\n        if (currentTab.canGoForward()) {\n            currentTab.moveForward()\n            loadFromBackStack()\n            return true\n        }\n        return false\n    }\n\n    fun backStackEmpty(): Boolean {\n        return currentTab.backStack.isEmpty()\n    }\n\n    fun onConfigurationChanged() {\n        leadImagesHandler.loadLeadImage()\n        bridge.execute(JavaScriptActionHandler.setTopMargin(leadImagesHandler.topMargin))\n    }\n\n    private fun commonSectionFetchOnCatch(caught: Throwable) {\n        if (!fragment.isAdded) {\n            return\n        }\n        fragment.requireActivity().invalidateOptionsMenu()\n        fragment.onPageLoadError(caught)\n    }\n\n    private fun pageLoad() {\n        pageLoadJob?.let {\n            if (it.isActive) {\n                it.cancel()\n            }\n        }\n        pageLoadJob = fragment.lifecycleScope.launch(CoroutineExceptionHandler { _, throwable ->\n            L.e(\"Page details network error: \", throwable)\n            commonSectionFetchOnCatch(throwable)\n        }) {\n            if (model.title == null) {\n                return@launch\n            }\n            val title = model.title!!\n            model.readingListPage = AppDatabase.instance.readingListPageDao().findPageInAnyList(title)\n\n            fragment.updateQuickActionsAndMenuOptions()\n            fragment.requireActivity().invalidateOptionsMenu()\n            fragment.callback()?.onPageUpdateProgressBar(true)\n            model.page = null\n            val delayLoadHtml = title.prefixedText.contains(\":\")\n            if (!delayLoadHtml) {\n                bridge.resetHtml(title)\n            }\n            if (title.namespace() === Namespace.SPECIAL) {\n                // Short-circuit the entire process of fetching the Summary, since Special: pages\n                // are not supported in RestBase.\n                bridge.resetHtml(title)\n                leadImagesHandler.loadLeadImage()\n                fragment.requireActivity().invalidateOptionsMenu()\n                fragment.onPageMetadataLoaded()\n                return@launch\n            }\n\n            val pageSummaryRequest = async {\n                ServiceFactory.getRest(title.wikiSite).getSummaryResponse(title.prefixedText, cacheControl = model.cacheControl.toString(),\n                    saveHeader = if (model.isInReadingList) OfflineCacheInterceptor.SAVE_HEADER_SAVE else null,\n                    langHeader = title.wikiSite.languageCode, titleHeader = UriUtil.encodeURL(title.prefixedText))\n            }\n            val makeWatchRequest = WikipediaApp.instance.isOnline && AccountUtil.isLoggedIn\n            val watchedRequest = async {\n                try {\n                    if (makeWatchRequest) {\n                        ServiceFactory.get(title.wikiSite)\n                            .getWatchedStatusWithCategories(title.prefixedText)\n                    } else if (WikipediaApp.instance.isOnline && !AccountUtil.isLoggedIn) {\n                        AnonymousNotificationHelper.maybeGetAnonUserInfo(title.wikiSite)\n                    } else {\n                        MwQueryResponse()\n                    }\n                } catch (_: MwNotLoggedInException) {\n                    AccountUtil.bailWithLogout()\n                    MwQueryResponse()\n                } catch (_: IOException) {\n                    L.w(\"Ignoring network error while fetching watched status.\")\n                    MwQueryResponse()\n                }\n            }\n            val categoriesRequest = async {\n                try {\n                    if (!makeWatchRequest && WikipediaApp.instance.isOnline) {\n                        ServiceFactory.get(title.wikiSite).getCategoriesProps(title.text)\n                    } else {\n                        MwQueryResponse()\n                    }\n                } catch (_: IOException) {\n                    L.w(\"Ignoring network error while fetching categories.\")\n                    MwQueryResponse()\n                }\n            }\n            val pageSummaryResponse = pageSummaryRequest.await()\n            val watchedResponse = watchedRequest.await()\n            val categoriesResponse = categoriesRequest.await()\n            val isWatched = watchedResponse.query?.firstPage()?.watched == true\n            val editCount = watchedResponse.query?.userInfo?.editCount ?: 0\n            val hasWatchlistExpiry = watchedResponse.query?.firstPage()?.hasWatchlistExpiry() == true\n            if (pageSummaryResponse.body() == null) {\n                throw RuntimeException(\"Summary response was invalid.\")\n            }\n            val redirectedFrom = if (pageSummaryResponse.raw().priorResponse?.isRedirect == true) model.title?.displayText else null\n            createPageModel(pageSummaryResponse, isWatched, hasWatchlistExpiry)\n            if (OfflineCacheInterceptor.SAVE_HEADER_SAVE == pageSummaryResponse.headers()[OfflineCacheInterceptor.SAVE_HEADER]) {\n                showPageOfflineMessage(pageSummaryResponse.headers().getInstant(\"date\"))\n            }\n\n            val categoryList = (categoriesResponse.query ?: watchedResponse.query)?.firstPage()?.categories?.map { category ->\n                Category(title = category.title, lang = title.wikiSite.languageCode)\n            }.orEmpty()\n            if (categoryList.isNotEmpty()) {\n                AppDatabase.instance.categoryDao().upsertAll(categoryList)\n            }\n\n            if (delayLoadHtml) {\n                bridge.resetHtml(title)\n            }\n            fragment.onPageMetadataLoaded(redirectedFrom = redirectedFrom, editCount = editCount)\n\n            if (AnonymousNotificationHelper.shouldCheckAnonNotifications(watchedResponse)) {\n                checkAnonNotifications(title)\n            }\n        }\n    }\n\n    private fun checkAnonNotifications(title: PageTitle) {\n        fragment.lifecycleScope.launch(CoroutineExceptionHandler { _, throwable ->\n            L.e(throwable)\n        }) {\n            val response = ServiceFactory.get(title.wikiSite)\n                .getLastModified(UserTalkAliasData.valueFor(title.wikiSite.languageCode) + \":\" + Prefs.lastAnonUserWithMessages)\n            if (AnonymousNotificationHelper.anonTalkPageHasRecentMessage(response, title)) {\n                fragment.showAnonNotification()\n            }\n        }\n    }\n\n    private fun showPageOfflineMessage(dateHeader: Instant?) {\n        if (dateHeader == null) {\n            return\n        }\n        val localDate = LocalDate.ofInstant(dateHeader, ZoneId.systemDefault())\n        val dateStr = DateUtil.getShortDateString(localDate)\n        Toast.makeText(fragment.requireContext().applicationContext,\n            fragment.getString(R.string.page_offline_notice_last_date, dateStr),\n            Toast.LENGTH_LONG).show()\n    }\n\n    private fun createPageModel(response: Response<PageSummary>,\n                                isWatched: Boolean,\n                                hasWatchlistExpiry: Boolean) {\n        if (response.body() == null) {\n            return\n        }\n        val pageSummary = response.body()\n        val page = pageSummary?.toPage(model.title)\n        model.page = page\n        model.isWatched = isWatched\n        model.hasWatchlistExpiry = hasWatchlistExpiry\n        model.title = page?.title\n        model.title?.let { title ->\n            if (!response.raw().request.url.fragment.isNullOrEmpty()) {\n                title.fragment = response.raw().request.url.fragment\n            }\n            if (title.description.isNullOrEmpty()) {\n                WikipediaApp.instance.appSessionEvent.noDescription()\n            }\n            if (!title.isMainPage) {\n                title.displayText = page?.summary?.displayTitle.orEmpty()\n            }\n            title.thumbUrl = pageSummary?.thumbnailUrl\n            leadImagesHandler.loadLeadImage()\n            fragment.requireActivity().invalidateOptionsMenu()\n\n            // Update our tab list to prevent ZH variants issue.\n            WikipediaApp.instance.tabList.getOrNull(WikipediaApp.instance.tabCount - 1)?.setBackStackPositionTitle(title)\n\n            // Update our history entry, in case the Title was changed (i.e. normalized)\n            model.curEntry?.let {\n                val entry = HistoryEntry(\n                    title,\n                    it.source,\n                    timestamp = it.timestamp\n                ).apply {\n                    referrer = it.referrer\n                    prevId = it.prevId\n                }\n                model.curEntry = entry\n\n                MainScope().launch {\n                    // Insert and/or update this history entry in the DB\n                    AppDatabase.instance.historyEntryDao().upsert(entry).run {\n                        model.curEntry?.id = this\n                    }\n\n                    // Update metadata in the DB\n                    AppDatabase.instance.pageImagesDao().upsertForMetadata(entry, title.thumbUrl, title.description, pageSummary?.coordinates?.latitude, pageSummary?.coordinates?.longitude)\n                }\n\n                // And finally, count this as a page view.\n                WikipediaApp.instance.appSessionEvent.pageViewed(entry)\n                ArticleLinkPreviewInteractionEvent(title.wikiSite.dbName(), pageSummary?.pageId ?: 0, entry.source).logNavigate()\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageFragmentLoadState.kt","kind":"class","line":39,"members":{"backStackEmpty":[105,107],"bridge":[42,42],"checkAnonNotifications":[225,235],"commonSectionFetchOnCatch":[114,120],"createPageModel":[248,304],"currentTab":[44,44],"fragment":[40,40],"goBack":[85,94],"goForward":[96,103],"leadImagesHandler":[43,43],"load":[47,54],"loadFromBackStack":[56,65],"model":[39,39],"onConfigurationChanged":[109,112],"pageLoad":[122,223],"pageLoadJob":[45,45],"setTab":[79,83],"showPageOfflineMessage":[237,246],"updateCurrentBackStackItem":[67,77],"webView":[41,41]},"supers":[]},"PageViewModel":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"]],"code":"class PageViewModel {\n\n    var page: Page? = null\n    var title: PageTitle? = null\n    var pendingHighlightText: String? = null\n    var curEntry: HistoryEntry? = null\n    var readingListPage: ReadingListPage? = null\n    var hasWatchlistExpiry = false\n    var isWatched = false\n    var forceNetwork = false\n    var isReadMoreLoaded = false\n    val isInReadingList get() = readingListPage != null\n    val cacheControl get() = if (forceNetwork) OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK else OkHttpConnectionFactory.CACHE_CONTROL_NONE\n    val shouldLoadAsMobileWeb get() =\n        title?.run { namespace() === Namespace.SPECIAL || isMainPage } ?: run { false } ||\n          page?.run { summary.ns !== Namespace.MAIN && summary.ns !== Namespace.USER &&\n                  summary.ns !== Namespace.PROJECT && summary.ns !== Namespace.DRAFT || isMainPage } ?: run { false }\n}","file":"app/src/main/java/org/wikipedia/page/PageViewModel.kt","kind":"class","line":7,"members":{"cacheControl":[19,19],"curEntry":[12,12],"forceNetwork":[16,16],"hasWatchlistExpiry":[14,14],"isInReadingList":[18,18],"isReadMoreLoaded":[17,17],"isWatched":[15,15],"page":[9,9],"pendingHighlightText":[11,11],"readingListPage":[13,13],"shouldLoadAsMobileWeb":[20,23],"title":[10,10]},"supers":[]},"ReferenceDialog":{"appearsIn":[["article","h-widgets","Screen \u00b7 view composition"]],"code":"class ReferenceDialog : ExtendedBottomSheetDialogFragment() {\n    interface Callback {\n        val linkHandler: LinkHandler\n        val referencesGroup: List<PageReferences.Reference>?\n        val selectedReferenceIndex: Int\n    }\n\n    private var _binding: FragmentReferencesPagerBinding? = null\n    private val binding get() = _binding!!\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentReferencesPagerBinding.inflate(inflater, container, false)\n        callback()?.let {\n            it.referencesGroup?.run {\n                binding.referenceTitleText.text = requireContext().getString(R.string.reference_title, \"\")\n                binding.referencePager.offscreenPageLimit = 2\n                binding.referencePager.adapter = ReferencesAdapter(this)\n                TabLayoutMediator(binding.pageIndicatorView, binding.referencePager) { _, _ -> }.attach()\n                binding.referencePager.setCurrentItem(it.selectedReferenceIndex, true)\n                binding.root.setLayoutDirectionByLang(it.linkHandler.wikiSite.languageCode)\n            } ?: return@let null\n        } ?: run {\n            dismiss()\n        }\n        return binding.root\n    }\n\n    override fun onStart() {\n        super.onStart()\n        if (callback()?.referencesGroup?.size == 1) {\n            binding.pageIndicatorView.visibility = View.GONE\n            binding.indicatorDivider.visibility = View.GONE\n        }\n        BottomSheetBehavior.from(binding.root.parent as View).peekHeight = DimenUtil.displayHeightPx\n    }\n\n    override fun onDestroyView() {\n        super.onDestroyView()\n        _binding = null\n    }\n\n    private fun processLinkTextWithAlphaReferences(linkText: String): String {\n        var newLinkText = linkText\n        val isLowercase = newLinkText.contains(\"lower\")\n        if (newLinkText.contains(\"alpha \")) {\n            val strings = newLinkText.split(\" \")\n            var alphaReference = StringUtil.getBase26String(strings.last().replace(\"]\", \"\").toInt())\n            alphaReference = if (isLowercase) alphaReference.lowercase(Locale.getDefault()) else alphaReference\n            newLinkText = alphaReference\n        }\n        return newLinkText.replace(\"[\\\\[\\\\]]\".toRegex(), \"\") + \".\"\n    }\n\n    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {\n        return BottomSheetDialog(requireActivity(), theme)\n    }\n\n    private inner class ViewHolder(val binding: ViewReferencePagerItemBinding) : RecyclerView.ViewHolder(binding.root) {\n        init {\n            binding.referenceText.movementMethod = LinkMovementMethodExt(callback()?.linkHandler)\n        }\n\n        fun bindItem(idText: CharSequence?, reference: PageReferences.Reference) {\n            binding.referenceId.text = idText\n            binding.root.post {\n                if (isAdded) {\n                    val contents = StringUtil.fromHtml(StringUtil.removeCiteMarkup(StringUtil.removeStyleTags(reference.html)))\n                    if (contents.isEmpty()) {\n                        // Inspect html for links without anchor text\n                        val links = Jsoup.parse(reference.html).select(\"a[href]\").map { it.attr(\"href\") }\n                        var tags = \"\"\n                        for (i in links.indices) {\n                            tags = tags.plus(\"<a href='${links[i]}'>[${i + 1}]</a>\")\n                        }\n                        binding.referenceText.text = StringUtil.fromHtml(tags)\n                        binding.referenceExtLink.isVisible = tags.isNotEmpty()\n                        return@post\n                    }\n                    binding.referenceExtLink.isVisible = false\n                    binding.referenceText.text = contents\n                }\n            }\n        }\n    }\n\n    private inner class ReferencesAdapter(val references: List<PageReferences.Reference>) : RecyclerView.Adapter<ViewHolder>() {\n        override fun getItemCount(): Int {\n            return references.size\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {\n            return ViewHolder(ViewReferencePagerItemBinding.inflate(LayoutInflater.from(context), parent, false))\n        }\n\n        override fun onBindViewHolder(holder: ViewHolder, position: Int) {\n            holder.bindItem(processLinkTextWithAlphaReferences(references[position].text), references[position])\n        }\n    }\n\n    private fun callback(): Callback? {\n        return getCallback(this, Callback::class.java)\n    }\n}","file":"app/src/main/java/org/wikipedia/page/references/ReferenceDialog.kt","kind":"class","line":26,"members":{"Callback":[27,31],"ReferencesAdapter":[111,123],"ViewHolder":[83,109],"_binding":[33,33],"binding":[34,34],"callback":[125,127],"onCreateDialog":[79,81],"onCreateView":[36,51],"onDestroyView":[62,65],"onStart":[53,60],"processLinkTextWithAlphaReferences":[67,77]},"supers":["ExtendedBottomSheetDialogFragment()"]},"Tab":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"]],"code":"@Serializable\nclass Tab {\n    val backStack = mutableListOf<PageBackStackItem>()\n\n    var backStackPosition: Int = -1\n        get() = if (field < 0) backStack.size - 1 else field\n\n    val backStackPositionTitle: PageTitle?\n        get() = if (backStack.isEmpty()) null else backStack[backStackPosition].title\n\n    fun setBackStackPositionTitle(title: PageTitle) {\n        backStackPositionTitle?.run {\n            backStack[backStackPosition].title = title\n        }\n    }\n\n    fun canGoBack(): Boolean {\n        return backStackPosition > 0\n    }\n\n    fun canGoForward(): Boolean {\n        return backStackPosition < backStack.size - 1\n    }\n\n    fun moveForward() {\n        if (backStackPosition < backStack.size - 1) {\n            backStackPosition++\n        }\n    }\n\n    fun moveBack() {\n        if (backStackPosition > 0) {\n            backStackPosition--\n        }\n    }\n\n    fun pushBackStackItem(item: PageBackStackItem) {\n        // remove all backstack items past the current position\n        while (backStack.size > backStackPosition + 1) {\n            backStack.removeAt(backStackPosition + 1)\n        }\n        backStack.add(item)\n        backStackPosition = backStack.size - 1\n    }\n\n    fun clearBackstack() {\n        backStack.clear()\n        backStackPosition = -1\n    }\n\n    fun squashBackstack() {\n        backStack.lastOrNull()?.let {\n            backStack.clear()\n            backStack.add(it)\n            backStackPosition = 0\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/tabs/Tab.kt","kind":"class","line":7,"members":{"backStack":[9,9],"backStackPosition":[11,11],"backStackPositionTitle":[14,14],"canGoBack":[23,25],"canGoForward":[27,29],"clearBackstack":[52,55],"moveBack":[37,41],"moveForward":[31,35],"pushBackStackItem":[43,50],"setBackStackPositionTitle":[17,21],"squashBackstack":[57,63]},"supers":[]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
